function GroupInfoMemberRow({
  directContact,
  isCurrentUser,
  member,
  profilePhotoHeaders
}: {
  directContact?: ChatContact;
  isCurrentUser: boolean;
  member: ChatGroupMember;
  profilePhotoHeaders?: Record<string, string>;
}) {
  const appTheme = useAppTheme();
  const subtitle = getGroupInfoMemberSubtitle(member, directContact, isCurrentUser);
  const badge = getGroupInfoMemberBadge(member);

  return (
    <View style={[
      styles.groupInfoMemberRow,
      {
        backgroundColor: appTheme.colors.surfaceElevated,
        borderBottomColor: appTheme.colors.divider
      }
    ]}>
      <ProfileAvatar
        headers={profilePhotoHeaders}
        name={member.displayName}
        size={44}
        uri={member.profilePhotoUrl || directContact?.profilePhotoUrl || null}
      />
      <View style={styles.chatText}>
        <Text numberOfLines={1} style={[styles.groupInfoMemberName, { color: appTheme.colors.ink }]}>
          {isCurrentUser ? 'You' : member.displayName}
        </Text>
        {subtitle ? (
          <Text numberOfLines={1} style={[styles.groupInfoMemberSubtitle, { color: appTheme.colors.muted }]}>{subtitle}</Text>
        ) : null}
      </View>
      {badge ? (
        <Text numberOfLines={1} style={[styles.groupInfoMemberBadge, { color: appTheme.colors.muted }]}>{badge}</Text>
      ) : null}
      <Feather color={appTheme.colors.muted} name="chevron-right" size={18} />
    </View>
  );
}

function GroupMembersModal({
  chat,
  currentUid,
  directContacts,
  isOpen,
  onAddMembers,
  onChangeSearch,
  onClose,
  profilePhotoHeaders,
  search
}: {
  chat: ChatItem | null;
  currentUid: string;
  directContacts: ChatContact[];
  isOpen: boolean;
  onAddMembers: () => void;
  onChangeSearch: (value: string) => void;
  onClose: () => void;
  profilePhotoHeaders?: Record<string, string>;
  search: string;
}) {
  const insets = useSafeAreaInsets();
  const modalTopPadding = getFullScreenModalTopPadding(insets.top);
  const directContactById = useMemo(() => new Map(
    directContacts.map((contact) => [contact.contactId, contact])
  ), [directContacts]);

  if (!chat || chat.chatType !== 'GROUP') {
    return null;
  }

  const members = chat.members || [];
  const visibleMembers = filterGroupInfoMembers(members, directContactById, currentUid, search);
  const memberCount = chat.memberCount ?? members.length;

  return (
    <Modal
      allowSwipeDismissal={Platform.OS === 'ios'}
      animationType="slide"
      onRequestClose={onClose}
      presentationStyle={getNativeFullHeightModalPresentationStyle()}
      transparent={false}
      visible={isOpen}
    >
      <View style={[styles.newChatModalScreen, { paddingTop: modalTopPadding }]}>
        <View style={styles.newChatHeader}>
          <Pressable
            accessibilityLabel="Close members"
            accessibilityRole="button"
            onPress={onClose}
            style={({ pressed }) => [styles.newChatHeaderIconButton, pressed && styles.pressed]}
          >
            <Feather color={colors.ink} name="x" size={24} />
          </Pressable>
          <View style={styles.newChatCenteredTitleWrap}>
            <Text numberOfLines={1} style={styles.newChatHeaderTitle}>Members</Text>
            <Text numberOfLines={1} style={styles.newChatHeaderSubtitle}>{formatGroupMemberCount(memberCount)}</Text>
          </View>
          <View style={styles.newChatHeaderSpacer} />
        </View>

        <ChatSearchBar
          onChangeText={onChangeSearch}
          placeholder="Search members"
          value={search}
        />

        <ScrollView
          keyboardDismissMode={getKeyboardDismissMode()}
          keyboardShouldPersistTaps="handled"
          showsVerticalScrollIndicator={false}
          style={styles.newChatContactList}
        >
          <View style={styles.groupInfoSection}>
            <GroupInfoSettingRow
              icon="plus"
              label="Add members"
              onPress={onAddMembers}
            />

            {visibleMembers.map((member) => (
              <GroupInfoMemberRow
                directContact={directContactById.get(member.uid)}
                isCurrentUser={member.uid === currentUid}
                key={member.uid || member.displayName}
                member={member}
                profilePhotoHeaders={profilePhotoHeaders}
              />
            ))}
          </View>

          {!visibleMembers.length ? (
            <Text style={styles.batchEmpty}>{search.trim() ? 'No members found' : 'No members yet'}</Text>
          ) : null}
        </ScrollView>
      </View>
    </Modal>
  );
}

function MessageListModal({
  chat,
  currentUid,
  isOpen,
  messages,
  mode,
  onChangeSearch,
  onClose,
  search,
  starredMessageIds
}: {
  chat: ChatItem | null;
  currentUid: string;
  isOpen: boolean;
  messages: ChatMessage[];
  mode: MessageListModalMode;
  onChangeSearch: (value: string) => void;
  onClose: () => void;
  search: string;
  starredMessageIds: Record<string, boolean>;
}) {
  const insets = useSafeAreaInsets();
  const modalTopPadding = getFullScreenModalTopPadding(insets.top);
  const senderNameByUid = useMemo(() => new Map(
    (chat?.members || []).map((member) => [member.uid, member.displayName])
  ), [chat?.members]);

  if (!chat || chat.chatType !== 'GROUP') {
    return null;
  }

  const visibleMessages = filterMessageListModalMessages(messages, mode, search, starredMessageIds);
  const title = mode === 'starred' ? 'Starred messages' : 'Search messages';

  return (
    <Modal
      allowSwipeDismissal={Platform.OS === 'ios'}
      animationType="slide"
      onRequestClose={onClose}
      presentationStyle={getNativeFullHeightModalPresentationStyle()}
      transparent={false}
      visible={isOpen}
    >
      <View style={[styles.newChatModalScreen, { paddingTop: modalTopPadding }]}>
        <View style={styles.newChatHeader}>
          <Pressable
            accessibilityLabel="Close messages"
            accessibilityRole="button"
            onPress={onClose}
            style={({ pressed }) => [styles.newChatHeaderIconButton, pressed && styles.pressed]}
          >
            <Feather color={colors.ink} name="x" size={24} />
          </Pressable>
          <View style={styles.newChatCenteredTitleWrap}>
            <Text numberOfLines={1} style={styles.newChatHeaderTitle}>{title}</Text>
            <Text numberOfLines={1} style={styles.newChatHeaderSubtitle}>{chat.title}</Text>
          </View>
          <View style={styles.newChatHeaderSpacer} />
        </View>

        {mode === 'search' ? (
          <ChatSearchBar
            onChangeText={onChangeSearch}
            placeholder="Search messages"
            value={search}
          />
        ) : null}

        <ScrollView
          keyboardDismissMode={getKeyboardDismissMode()}
          keyboardShouldPersistTaps="handled"
          showsVerticalScrollIndicator={false}
          style={styles.newChatContactList}
        >
          {visibleMessages.map((message) => (
            <View key={message.messageId} style={styles.messageListRow}>
              <View style={styles.messageListIcon}>
                <Feather
                  color={message.senderUid === currentUid ? colors.primary : '#64748B'}
                  name={mode === 'starred' ? 'star' : 'message-circle'}
                  size={18}
                />
              </View>
              <View style={styles.chatText}>
                <View style={styles.messageListMetaRow}>
                  <Text numberOfLines={1} style={styles.messageListSender}>
                    {getGroupMessageSenderName(message, currentUid, senderNameByUid)}
                  </Text>
                  <Text numberOfLines={1} style={styles.messageListTime}>{formatMessageTime(message.sentAt)}</Text>
                </View>
                <Text numberOfLines={2} style={styles.messageListPreview}>
                  {getMessageListPreview(message)}
                </Text>
              </View>
            </View>
          ))}

          {!visibleMessages.length ? (
            <Text style={styles.batchEmpty}>
              {mode === 'starred'
                ? 'No starred messages yet'
                : search.trim()
                  ? 'No messages found'
                  : 'Type to search messages'}
            </Text>
          ) : null}
        </ScrollView>
      </View>
    </Modal>
  );
}

function GroupSwitcherModal({
  companyName,
  groups,
  isLoading,
  isOpen,
  onAddGroup,
  onClose,
  onOpenGroup,
  selectedGroupId
}: {
  companyName: string;
  groups: TenantGroup[];
  isLoading: boolean;
  isOpen: boolean;
  onAddGroup: () => void;
  onClose: () => void;
  onOpenGroup: (group: TenantGroup) => void;
  selectedGroupId: string | null;
}) {
  const insets = useSafeAreaInsets();
  const modalTopPadding = getFullScreenModalTopPadding(insets.top);
  const visibleGroups = groups.filter((group) => !group.systemManaged || !group.isDepartmentDefault);

  return (
    <Modal
      allowSwipeDismissal={Platform.OS === 'ios'}
      animationType="slide"
      onRequestClose={onClose}
      presentationStyle={getNativeFullHeightModalPresentationStyle()}
      transparent={false}
      visible={isOpen}
    >
      <View style={[styles.newChatModalScreen, { paddingTop: modalTopPadding }]}>
        <View style={styles.newChatHeader}>
          <View style={styles.newChatHeaderSpacer} />
          <Text numberOfLines={1} style={styles.newChatHeaderTitle}>{companyName}</Text>
          <Pressable
            accessibilityLabel="Close groups"
            accessibilityRole="button"
            onPress={onClose}
            style={({ pressed }) => [styles.newChatHeaderIconButton, pressed && styles.pressed]}
          >
            <Feather color={colors.ink} name="x" size={24} />
          </Pressable>
        </View>

        <Text style={styles.groupSwitcherSectionTitle}>Groups you're in</Text>

        {isLoading && !visibleGroups.length ? (
          <View style={styles.loadingRow}>
            <ActivityIndicator color={colors.primary} />
          </View>
        ) : (
          <ScrollView
            keyboardShouldPersistTaps="handled"
            showsVerticalScrollIndicator={false}
            style={styles.groupSwitcherList}
          >
            {visibleGroups.map((group) => (
              <Pressable
                accessibilityLabel={`Open ${group.name}`}
                accessibilityRole="button"
                key={group.groupId}
                onPress={() => onOpenGroup(group)}
                style={({ pressed }) => [
                  styles.groupSwitcherRow,
                  selectedGroupId === group.groupId && styles.groupSwitcherRowActive,
                  pressed && styles.pressed
                ]}
              >
                <View style={styles.groupIcon}>
                  <Ionicons color={colors.primary} name="people" size={21} />
                </View>
                <View style={styles.chatText}>
                  <Text numberOfLines={1} style={styles.chatTitle}>{group.name}</Text>
                  <Text numberOfLines={1} style={styles.chatPreview}>{getGroupSubtitle(group)}</Text>
                </View>
                <Text numberOfLines={1} style={styles.groupMeta}>
                  {group.memberCount === 1 ? '1 member' : `${group.memberCount} members`}
                </Text>
              </Pressable>
            ))}

            {!visibleGroups.length ? (
              <Text style={styles.batchEmpty}>No groups yet</Text>
            ) : null}
          </ScrollView>
        )}

        <Pressable
          accessibilityLabel="Add group"
          accessibilityRole="button"
          android_ripple={androidButtonRipple}
          onPress={onAddGroup}
          style={({ pressed }) => [styles.groupSwitcherAddButton, pressed && styles.pressed]}
        >
          <Feather color="#FFFFFF" name="plus" size={19} />
          <Text style={styles.groupSwitcherAddText}>Add group</Text>
        </Pressable>
      </View>
    </Modal>
  );
}

