function FooterTabButton({
  active,
  badgeCount = 0,
  minHeight,
  onPress,
  profile,
  profilePhotoHeaders,
  tab
}: {
  active: boolean;
  badgeCount?: number;
  minHeight: number;
  onPress: () => void;
  profile: CurrentUserProfile | null;
  profilePhotoHeaders?: Record<string, string>;
  tab: FooterTab;
}) {
  const appTheme = useAppTheme();
  const activeProgress = useRef(new Animated.Value(active ? 1 : 0)).current;

  useEffect(() => {
    Animated.spring(activeProgress, {
      damping: 16,
      mass: 0.82,
      stiffness: 190,
      toValue: active ? 1 : 0,
      useNativeDriver: true
    }).start();
  }, [active, activeProgress]);

  const pillScale = activeProgress.interpolate({
    inputRange: [0, 1],
    outputRange: [0.94, 1]
  });
  const pillOpacity = activeProgress.interpolate({
    inputRange: [0, 1],
    outputRange: [0, 1]
  });
  const contentScale = activeProgress.interpolate({
    inputRange: [0, 1],
    outputRange: [1, 1.04]
  });

  return (
    <Pressable
      accessibilityLabel={tab}
      accessibilityRole="button"
      accessibilityState={{ selected: active }}
      onPress={onPress}
      style={({ pressed }) => [
        styles.footerTab,
        { minHeight },
        pressed && styles.pressed
      ]}
    >
      <Animated.View
        pointerEvents="none"
        style={[
          styles.footerTabActivePill,
          {
            backgroundColor: appTheme.colors.footerActive,
            opacity: pillOpacity,
            transform: [{ scale: pillScale }]
          }
        ]}
      />
      <Animated.View style={[
        styles.footerTabContent,
        { transform: [{ scale: contentScale }] }
      ]}>
	        <FooterIcon
	          active={active}
	          profile={profile}
	          profilePhotoHeaders={profilePhotoHeaders}
	          tab={tab}
	        />
	        {badgeCount > 0 ? (
	          <View style={styles.footerTabBadge}>
	            <Text style={styles.footerTabBadgeText}>{badgeCount > 99 ? '99+' : badgeCount}</Text>
	          </View>
	        ) : null}
	        <Text style={[
          styles.footerTabText,
          active && styles.footerTabTextActive,
          { color: active ? appTheme.colors.primary : appTheme.colors.ink }
        ]}>
          {tab}
        </Text>
      </Animated.View>
    </Pressable>
  );
}

function FooterIcon({
  active,
  profile,
  profilePhotoHeaders,
  tab
}: {
  active: boolean;
  profile: CurrentUserProfile | null;
  profilePhotoHeaders?: Record<string, string>;
  tab: FooterTab;
}) {
  const appTheme = useAppTheme();
  const iconColor = active ? appTheme.colors.primary : appTheme.colors.mutedStrong;

  if (tab === 'You') {
    return (
      <View style={[
        styles.footerProfileAvatar,
        active && styles.footerProfileAvatarActive,
        active && {
          backgroundColor: appTheme.colors.primarySoft,
          borderColor: appTheme.colors.primary
        }
      ]}>
        <ProfileAvatar
          headers={profilePhotoHeaders}
          name={profile?.displayName || 'You'}
          size={28}
          uri={profile?.profilePhotoUrl}
        />
      </View>
    );
  }

  if (tab === 'Employees') {
    return <Ionicons color={iconColor} name={active ? 'people' : 'people-outline'} size={27} />;
  }

  if (tab === 'Calls') {
    return <Ionicons color={iconColor} name={active ? 'call' : 'call-outline'} size={27} />;
  }

  if (tab === 'Groups') {
    return <Ionicons color={iconColor} name={active ? 'albums' : 'albums-outline'} size={27} />;
  }

  if (tab === 'Settings') {
    return <Ionicons color={iconColor} name={active ? 'settings' : 'settings-outline'} size={27} />;
  }

  return <Ionicons color={iconColor} name={active ? 'chatbubble-ellipses' : 'chatbubble-ellipses-outline'} size={27} />;
}

function sortByName<T extends { name: string }>(records: T[]): T[] {
  return [...records].sort((first, second) => first.name.localeCompare(second.name));
}

function getGroupSubtitle(group: TenantGroup): string {
  if (group.isDepartmentDefault) {
    return group.departmentName ? `${group.departmentName} department` : 'Department group';
  }

  if (group.scope === 'DEPARTMENT') {
    return group.departmentName ? `${group.departmentName} group` : 'Department group';
  }

  return 'Company group';
}

function getAddableGroupSubtitle(group: AddableChatGroup): string {
  if (group.isDepartmentDefault) {
    return group.departmentName ? `${group.departmentName} department` : 'Department group';
  }

  const memberCount = group.memberCount === 1 ? '1 member' : `${group.memberCount} members`;

  if (group.scope === 'DEPARTMENT' && group.departmentName) {
    return `${group.departmentName} - ${memberCount}`;
  }

  return memberCount;
}

function hasPermission(permissions: string[], permission: UserPermission): boolean {
  return permissions.includes(permission);
}

function getDeviceIconName(platform: string): React.ComponentProps<typeof Feather>['name'] {
  if (platform === 'ios' || platform === 'android') {
    return 'smartphone';
  }

  if (platform === 'web') {
    return 'monitor';
  }

  return 'hard-drive';
}

function formatDevicePlatform(platform: string): string {
  if (platform === 'ios') {
    return 'iOS';
  }

  if (platform === 'android') {
    return 'Android';
  }

  if (platform === 'web') {
    return 'Web';
  }

  return 'Unknown device';
}

function formatSecurityDate(value: string): string {
  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return '';
  }

  return date.toLocaleDateString(undefined, {
    day: 'numeric',
    month: 'short',
    year: 'numeric'
  });
}

function getEmployeeActionOptions(employee: EmployeeListItem): EmployeeActionOption[] {
  const status = employee.statusValue.toUpperCase();
  const changeRoleOption: EmployeeActionOption = {
    action: 'CHANGE_ROLE',
    confirmButton: 'Change',
    confirmMessage: (employeeName) =>
      `${employeeName}'s company role and role permissions will be updated.`,
    confirmTitle: 'Change role?',
    label: 'Change role',
    successMessage: (employeeName) => `${employeeName}'s role has been updated.`,
    successTitle: 'Role updated'
  };
  const departmentAdminOption: EmployeeActionOption = employee.baseRole === 'DEPT_ADMIN'
    ? {
        action: 'REMOVE_DEPT_ADMIN',
        confirmButton: 'Remove',
        confirmMessage: (employeeName) =>
          `${employeeName} will remain an employee, but will no longer be marked as a department admin.`,
        confirmTitle: 'Remove department admin?',
        label: 'Remove Dept Admin',
        successMessage: (employeeName) => `${employeeName} is no longer marked as a department admin.`,
        successTitle: 'Department admin removed'
      }
    : {
        action: 'ASSIGN_DEPT_ADMIN',
        confirmButton: 'Assign',
        confirmMessage: (employeeName) =>
          `${employeeName} will be marked as a department admin for their assigned department.`,
        confirmTitle: 'Assign department admin?',
        label: 'Assign Dept Admin',
        successMessage: (employeeName) => `${employeeName} is now marked as a department admin.`,
        successTitle: 'Department admin assigned'
      };
  const deactivateOption: EmployeeActionOption = {
    action: 'DEACTIVATE',
    confirmButton: 'Deactivate',
    confirmMessage: (employeeName) =>
      `${employeeName} will lose access to this organization and all registered devices will be revoked.`,
    confirmTitle: 'Deactivate employee?',
    label: status === 'INVITED' ? 'Cancel invite' : 'Deactivate',
    reason: status === 'INVITED' ? 'Invite cancelled by organization admin' : 'Deactivated by organization admin',
    successMessage: (employeeName) => `${employeeName} no longer has active access.`,
    successTitle: status === 'INVITED' ? 'Invite cancelled' : 'Employee deactivated'
  };
  const archiveOption: EmployeeActionOption = {
    action: 'ARCHIVE',
    confirmButton: 'Archive',
    confirmMessage: (employeeName) =>
      `${employeeName} will be archived and blocked from future organization access.`,
    confirmTitle: 'Archive employee?',
    label: 'Archive',
    reason: 'Archived by organization admin',
    successMessage: (employeeName) => `${employeeName} has been archived.`,
    successTitle: 'Employee archived'
  };
  const reactivateOption: EmployeeActionOption = {
    action: 'REACTIVATE',
    confirmButton: 'Reactivate',
    confirmMessage: (employeeName) =>
      `${employeeName} will regain organization access after phone verification. Devices manually revoked by an admin remain blocked.`,
    confirmTitle: 'Reactivate employee?',
    label: 'Reactivate',
    reason: 'Reactivated by organization admin',
    successMessage: (employeeName) => `${employeeName} can sign in again after phone verification.`,
    successTitle: 'Employee reactivated'
  };
  const deleteOption: EmployeeActionOption = {
    action: 'DELETE',
    confirmButton: 'Delete',
    confirmMessage: (employeeName) =>
      `${employeeName} will be deleted from active employee access. Their devices will be revoked, but the record can still be reactivated or permanently removed later.`,
    confirmTitle: 'Delete employee?',
    label: 'Delete',
    reason: 'Deleted by organization admin',
    successMessage: (employeeName) => `${employeeName} has been deleted from active access.`,
    successTitle: 'Employee deleted'
  };
  const permanentDeleteOption: EmployeeActionOption = {
    action: 'PERMANENT_DELETE',
    confirmButton: 'Remove',
    confirmMessage: (employeeName) =>
      `${employeeName} will be permanently removed from the employee directory. This clears the approval record for this phone number and cannot be undone.`,
    confirmTitle: 'Permanently remove employee?',
    label: 'Permanently remove',
    reason: 'Permanently removed by organization admin',
    successMessage: (employeeName) => `${employeeName} has been permanently removed.`,
    successTitle: 'Employee removed'
  };
  const removeInviteOption: EmployeeActionOption = {
    action: 'REMOVE_INVITE',
    confirmButton: 'Remove',
    confirmMessage: (employeeName) =>
      `${employeeName}'s pending invite will be removed from this organization. This clears the phone number so it can be invited correctly later.`,
    confirmTitle: 'Remove invite?',
    label: 'Remove invite',
    reason: 'Invite removed by organization admin',
    successMessage: (employeeName) => `${employeeName}'s invite has been removed.`,
    successTitle: 'Invite removed'
  };

  if (status === 'ACTIVE') {
    return [changeRoleOption, departmentAdminOption, deactivateOption, archiveOption, deleteOption];
  }

  if (status === 'INVITED') {
    return [changeRoleOption, departmentAdminOption, removeInviteOption];
  }

  if (status === 'DEACTIVATED' || status === 'SUSPENDED') {
    return [reactivateOption, archiveOption, deleteOption];
  }

  if (status === 'ARCHIVED') {
    return [reactivateOption, deleteOption];
  }

  if (status === 'DELETED') {
    return [reactivateOption, permanentDeleteOption];
  }

  return [];
}

function isEmployeeLifecycleAction(action: EmployeeAction): action is EmployeeLifecycleAction {
  return action === 'DEACTIVATE' ||
    action === 'ARCHIVE' ||
    action === 'DELETE' ||
    action === 'ANONYMIZE' ||
    action === 'PERMANENT_DELETE' ||
    action === 'REMOVE_INVITE' ||
    action === 'REACTIVATE';
}

function isDestructiveEmployeeAction(action: EmployeeAction): boolean {
  return action === 'DELETE' ||
    action === 'ANONYMIZE' ||
    action === 'PERMANENT_DELETE' ||
    action === 'REMOVE_INVITE';
}

function getErrorMessage(error: unknown, fallback: string): string {
  if (error instanceof Error && error.message) {
    return error.message;
  }

  return fallback;
}

function getTranslationLanguageOption(
  options: TranscriptLanguageOption[],
  code: ChatTranscriptLanguageCode
): TranscriptLanguageOption {
  return options.find((option) => option.code === code) || {
    code,
    label: code,
    status: 'available'
  };
}

function getCompactLanguageLabel(option: TranscriptLanguageOption): string {
  return option.label.replace(/\s*\([^)]*\)/g, '').trim() || option.label;
}

function createSynzappCallId(): string {
  const segment = (length: number) => Array.from({ length }, () =>
    Math.floor(Math.random() * 16).toString(16)
  ).join('');

  return `${segment(8)}-${segment(4)}-4${segment(3)}-${((8 + Math.floor(Math.random() * 4)).toString(16))}${segment(3)}-${segment(12)}`;
}

function getSynzappWebRtcRuntime(): WebRtcRuntime {
  try {
    const runtime = require('react-native-webrtc') as WebRtcRuntime;

    if (!runtime?.RTCPeerConnection || !runtime.mediaDevices?.getUserMedia) {
      throw new Error('Calling is not available in this installed build.');
    }

    return runtime;
  } catch {
    throw new Error('Please install the latest Synzapp development build to use secure calls.');
  }
}

function getOptionalCallKeepRuntime(): any | null {
  if (Platform.OS === 'android') {
    return null;
  }

  try {
    const module = require('react-native-callkeep');

    return module?.default || module;
  } catch {
    return null;
  }
}

function getOptionalInCallManagerRuntime(): any | null {
  try {
    const module = require('react-native-incall-manager');

    return module?.default || module;
  } catch {
    return null;
  }
}

function getOptionalRtcView(): React.ComponentType<any> | null {
  try {
    const runtime = require('react-native-webrtc') as WebRtcRuntime;

    return runtime?.RTCView || null;
  } catch {
    return null;
  }
}

function getSynzappCallStatusLabel(callState: ActiveSynzappCall): string {
  if (callState.status === 'ringing') {
    return 'Incoming secure call...';
  }

  if (callState.status === 'calling') {
    return callState.call.mode === 'video' ? 'Video calling...' : 'Calling...';
  }

  if (callState.status === 'connecting') {
    return 'Connecting securely...';
  }

  if (callState.status === 'connected') {
    return callState.call.chatType === 'GROUP' ? 'Group call connected' : 'Call connected';
  }

  return 'Ending call...';
}

function shouldRenderSynzappCallOverlay(callState: ActiveSynzappCall | null): boolean {
  if (!callState) {
    return false;
  }

  return !(
    Platform.OS === 'ios' &&
    callState.direction === 'incoming' &&
    callState.status === 'ringing' &&
    callState.isNativePresented
  );
}

function createRtcSessionDescription(runtime: WebRtcRuntime, payload: unknown): unknown {
  return runtime.RTCSessionDescription ? new runtime.RTCSessionDescription(payload) : payload;
}

function createRtcIceCandidate(runtime: WebRtcRuntime, payload: unknown): unknown {
  return runtime.RTCIceCandidate ? new runtime.RTCIceCandidate(payload) : payload;
}

function serializeSynzappCallSignalPayload(payload: unknown): unknown {
  if (!payload || typeof payload !== 'object') {
    return payload;
  }

  if ('toJSON' in payload && typeof (payload as { toJSON?: () => unknown }).toJSON === 'function') {
    return (payload as { toJSON: () => unknown }).toJSON();
  }

  return payload;
}

function getNativeCallKeepEndReason(RNCallKeep: any, reason: SynzappCallEndReason): number {
  const endReasons = RNCallKeep?.CONSTANTS?.END_CALL_REASONS || {};

  if (reason === 'missed') {
    return endReasons.MISSED || endReasons.UNANSWERED || 6;
  }

  if (reason === 'failed') {
    return endReasons.FAILED || 1;
  }

  if (reason === 'declined' || reason === 'busy') {
    return endReasons.DECLINED_ELSEWHERE || endReasons.REMOTE_ENDED || 2;
  }

  return endReasons.REMOTE_ENDED || 2;
}

function partitionCallSignals<T>(
  items: T[],
  predicate: (item: T) => boolean
): [T[], T[]] {
  const matchingItems: T[] = [];
  const remainingItems: T[] = [];

  items.forEach((item) => {
    if (predicate(item)) {
      matchingItems.push(item);
    } else {
      remainingItems.push(item);
    }
  });

  return [matchingItems, remainingItems];
}

function omitRecordKey<T>(record: Record<string, T>, key: string): Record<string, T> {
  const nextRecord = { ...record };
  delete nextRecord[key];
  return nextRecord;
}

function isRecipientDeviceNotReadyError(error: unknown): boolean {
  return error instanceof Error &&
    /recipient.*active device|does not have an active device|group members need to open synzapp/i.test(error.message);
}

function isNetworkUnavailableError(error: unknown): boolean {
  return error instanceof Error &&
    /network request failed|failed to fetch|networkerror|internet connection|offline|timed out|connection/i.test(error.message);
}

function isChatUnavailableForCurrentUserError(error: unknown): boolean {
  return error instanceof Error &&
    /chat.*not found|not available for your account|no longer have access|not a member|access.*group/i.test(error.message);
}

function getRecipientDeviceNotReadyMessage(name: string): string {
  return `${name} needs to open Synzapp once before encrypted chat is available.`;
}

function getChatDeviceNotReadyMessage(chat: ChatItem): string {
  if (chat.chatType === 'GROUP') {
    return `Group members need to open Synzapp once before encrypted chat is available in ${chat.title}.`;
  }

  return getRecipientDeviceNotReadyMessage(chat.title);
}

function isRealtimeSessionVerificationError(message: string): boolean {
  return /realtime session could not be verified|secure session could not be verified/i.test(message);
}

function formatChatListTime(value: string): string {
  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return '';
  }

  const now = new Date();
  const startOfToday = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
  const startOfMessageDay = new Date(date.getFullYear(), date.getMonth(), date.getDate()).getTime();
  const oneDayMs = 24 * 60 * 60 * 1000;

  if (startOfMessageDay === startOfToday) {
    return date.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
  }

  if (startOfToday - startOfMessageDay === oneDayMs) {
    return 'Yesterday';
  }

  return date.toLocaleDateString([], { month: 'short', day: 'numeric' });
}

function formatMessageTime(value: string): string {
  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return '';
  }

  return date.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
}

function formatMessageDeliveryStatus(status: ChatDeliveryStatus | null): string {
  if (status === 'read') {
    return 'Seen';
  }

  if (status === 'delivered') {
    return 'Delivered';
  }

  if (status === 'sent') {
    return 'Sent';
  }

  if (status === 'queued') {
    return 'Queued';
  }

  return '';
}

function getCurrentUserReactionEmojis(
  reactions: ChatMessageReaction[] | undefined,
  currentUid: string
): string[] {
  const emojis = new Set<string>();

  reactions?.forEach((reaction) => {
    if (reaction.uid === currentUid && reaction.emoji.trim()) {
      emojis.add(reaction.emoji.trim());
    }
  });

  return [...emojis];
}

function formatMessageReactionBadge(reactions: ChatMessageReaction[] | undefined): string {
  if (!reactions?.length) {
    return '';
  }

  const reactionCounts = new Map<string, number>();

  reactions.forEach((reaction) => {
    const emoji = reaction.emoji.trim();

    if (!emoji) {
      return;
    }

    reactionCounts.set(emoji, (reactionCounts.get(emoji) || 0) + 1);
  });

  return [...reactionCounts.entries()]
    .map(([emoji, count]) => count > 1 ? `${emoji} ${count}` : emoji)
    .join(' ');
}

function extractReactionMapFromMessages(messages: ChatMessage[]): ChatMessageReactionMap {
  const reactionMap: ChatMessageReactionMap = {};

  messages.forEach((message) => {
    if (message.reactions?.length) {
      reactionMap[message.messageId] = sortMessageReactions(message.reactions);
    }
  });

  return reactionMap;
}

function applyReactionMapToMessages(
  messages: ChatMessage[],
  reactionMap: ChatMessageReactionMap
): ChatMessage[] {
  return messages.map((message) => ({
    ...message,
    reactions: reactionMap[message.messageId] || []
  }));
}

function upsertMessageReaction(
  reactionMap: ChatMessageReactionMap,
  messageId: string,
  uid: string,
  emoji: string
): ChatMessageReactionMap {
  const safeEmoji = emoji.trim();
  const nextReactionMap: ChatMessageReactionMap = { ...reactionMap };
  const currentMessageReactions = nextReactionMap[messageId] || [];
  const hasCurrentEmoji = currentMessageReactions.some((reaction) =>
    reaction.uid === uid && reaction.emoji === safeEmoji
  );
  const reactionsWithoutCurrentEmoji = currentMessageReactions.filter((reaction) =>
    !(reaction.uid === uid && reaction.emoji === safeEmoji)
  );

  if (!safeEmoji) {
    const reactionsWithoutCurrentUser = currentMessageReactions.filter((reaction) => reaction.uid !== uid);

    if (reactionsWithoutCurrentUser.length) {
      nextReactionMap[messageId] = reactionsWithoutCurrentUser;
    } else {
      delete nextReactionMap[messageId];
    }

    return nextReactionMap;
  }

  if (hasCurrentEmoji) {
    if (reactionsWithoutCurrentEmoji.length) {
      nextReactionMap[messageId] = sortMessageReactions(reactionsWithoutCurrentEmoji);
    } else {
      delete nextReactionMap[messageId];
    }

    return nextReactionMap;
  }

  const currentUserReactions = reactionsWithoutCurrentEmoji.filter((reaction) => reaction.uid === uid);
  const otherUserReactions = reactionsWithoutCurrentEmoji.filter((reaction) => reaction.uid !== uid);
  const nextCurrentUserReactions = [
    ...currentUserReactions,
    {
      emoji: safeEmoji,
      reactedAt: new Date().toISOString(),
      uid
    }
  ].slice(-12);

  nextReactionMap[messageId] = sortMessageReactions([
    ...otherUserReactions,
    ...nextCurrentUserReactions
  ]);

  return nextReactionMap;
}

function sortMessageReactions(reactions: ChatMessageReaction[]): ChatMessageReaction[] {
  return [...reactions].sort((first, second) => first.reactedAt.localeCompare(second.reactedAt));
}

function buildReplyReference(message: ChatMessage): ChatReplyReference {
  return {
    messageId: message.messageId,
    senderUid: message.senderUid,
    sentAt: message.sentAt,
    text: formatReplyPreviewText(getChatMessagePreview(message)).slice(0, 500)
  };
}

function getReplyAuthorLabel(senderUid: string, currentUid: string, contactName: string): string {
  if (senderUid && currentUid && senderUid === currentUid) {
    return 'You';
  }

  return contactName || 'Message';
}

function applyMediaReviewQualityMode(
  media: LocalChatMediaInput,
  qualityMode: ChatMediaQualityMode
): LocalChatMediaInput {
  if (
    qualityMode === 'hd' &&
    media.originalUri &&
    media.originalSizeBytes &&
    media.originalSizeBytes > 0 &&
    media.originalSizeBytes <= CHAT_MEDIA_LIMITS[media.kind]
  ) {
    return {
      ...media,
      contentType: media.originalContentType || media.contentType,
      height: media.originalHeight || media.height,
      qualityMode: 'hd',
      sizeBytes: media.originalSizeBytes,
      uri: media.originalUri,
      width: media.originalWidth || media.width
    };
  }

  return {
    ...media,
    qualityMode: 'standard'
  };
}

function buildLocalChatMediaAttachment(media: LocalChatMediaInput): ChatMediaAttachment {
  return {
    contentType: media.contentType,
    durationMs: media.durationMs,
    fileName: media.fileName,
    height: media.height,
    kind: media.kind,
    localUri: media.uri,
    qualityMode: media.qualityMode,
    sizeBytes: media.sizeBytes,
    thumbnailContentType: media.thumbnailContentType,
    thumbnailDataUrl: media.thumbnailDataUrl,
    thumbnailHeight: media.thumbnailHeight,
    thumbnailWidth: media.thumbnailWidth,
    transferProgress: 0,
    transferStatus: 'queued',
    width: media.width
  };
}

function getMessageMedia(message: ChatMessage): ChatMediaAttachment | null {
  return message.media || message.mediaItems?.[0] || message.image || null;
}

function getMessageMediaItems(message: ChatMessage): ChatMediaAttachment[] {
  if (Array.isArray(message.mediaItems) && message.mediaItems.length) {
    return message.mediaItems;
  }

  const media = getMessageMedia(message);

  return media ? [media] : [];
}

function mergeSyncedMessageWithPendingLocalMedia(
  syncedMessage: ChatMessage,
  pendingMessage: ChatMessage | null
): ChatMessage {
  if (!pendingMessage) {
    return syncedMessage;
  }

  const pendingMediaItems = getMessageMediaItems(pendingMessage);
  const nextMedia = syncedMessage.media
    ? mergeSyncedMediaWithPendingLocalMedia(syncedMessage.media, pendingMediaItems[0] || getMessageMedia(pendingMessage))
    : null;
  const nextMediaItems = Array.isArray(syncedMessage.mediaItems) && syncedMessage.mediaItems.length
    ? syncedMessage.mediaItems.map((media, index) => mergeSyncedMediaWithPendingLocalMedia(media, pendingMediaItems[index]))
    : [];

  return {
    ...syncedMessage,
    image: nextMedia?.kind === 'image'
      ? {
          ...nextMedia,
          contentType: 'image/jpeg',
          height: nextMedia.height || 1,
          kind: 'image',
          width: nextMedia.width || 1
        } as ChatImageAttachment
      : syncedMessage.image,
    media: nextMedia,
    mediaItems: nextMediaItems
  };
}

function mergeSyncedMediaWithPendingLocalMedia(
  syncedMedia: ChatMediaAttachment,
  pendingMedia?: ChatMediaAttachment | null
): ChatMediaAttachment {
  if (!pendingMedia?.localUri || pendingMedia.localUri.startsWith('data:')) {
    return syncedMedia;
  }

  const isSameMedia = Boolean(
    syncedMedia.mediaId && pendingMedia.mediaId && syncedMedia.mediaId === pendingMedia.mediaId
  ) || (
    syncedMedia.kind === pendingMedia.kind &&
    syncedMedia.fileName === pendingMedia.fileName &&
    syncedMedia.sizeBytes === pendingMedia.sizeBytes
  );

  if (!isSameMedia) {
    return syncedMedia;
  }

  return {
    ...syncedMedia,
    localUri: pendingMedia.localUri,
    thumbnailContentType: syncedMedia.thumbnailContentType || pendingMedia.thumbnailContentType,
    thumbnailDataUrl: syncedMedia.thumbnailDataUrl || pendingMedia.thumbnailDataUrl,
    thumbnailHeight: syncedMedia.thumbnailHeight || pendingMedia.thumbnailHeight,
    thumbnailWidth: syncedMedia.thumbnailWidth || pendingMedia.thumbnailWidth,
    transferProgress: 1,
    transferStatus: 'available'
  };
}

function getMediaLocalUri(media: ChatMediaAttachment | null): string {
  if (!media) {
    return '';
  }

  return media.localUri ||
    (typeof (media as ChatImageAttachment).dataUrl === 'string'
      ? (media as ChatImageAttachment).dataUrl || ''
      : '');
}

function getMediaPreviewUri(media: ChatMediaAttachment | null): string {
  if (!media) {
    return '';
  }

  if (media.kind === 'video') {
    return media.thumbnailDataUrl || getMediaLocalUri(media) || '';
  }

  return getMediaLocalUri(media) || media.thumbnailDataUrl || '';
}

function getLocalChatMediaPreviewUri(media: LocalChatMediaInput | null): string {
  if (!media) {
    return '';
  }

  return media.thumbnailDataUrl || (media.kind === 'image' ? media.uri : '');
}

function getMediaPreparationKey(messageId: string, media: ChatMediaAttachment, index: number): string {
  return `${messageId}:${media.mediaId || media.localUri || media.fileName}:${index}`;
}

function isAudioAttachment(media: ChatMediaAttachment): boolean {
  const contentType = (media.contentType || '').trim().toLowerCase();

  if (contentType.startsWith('audio/')) {
    return true;
  }

  const extension = getReadableFileExtension(media.fileName).toLowerCase();

  return Boolean(extension && [
    'aac',
    'aif',
    'aiff',
    'amr',
    'flac',
    'm4a',
    'mp3',
    'oga',
    'ogg',
    'opus',
    'wav',
    'weba',
    'wma'
  ].includes(extension));
}

function isMediaTransferActive(media: ChatMediaAttachment): boolean {
  return media.transferStatus === 'queued' ||
    media.transferStatus === 'uploading' ||
    media.transferStatus === 'downloading';
}

function shouldSkipAutomaticMediaDownload(
  media: ChatMediaAttachment,
  networkPolicy = buildChatMediaNetworkPolicy(null)
): boolean {
  if (media.kind === 'video') {
    return true;
  }

  const sizeBytes = Math.max(media.sizeBytes || 0, 0);

  if (media.kind === 'image') {
    if (!networkPolicy.canAutoDownloadImages) {
      return true;
    }

    return networkPolicy.isConnectionExpensive &&
      sizeBytes > CHAT_CELLULAR_IMAGE_AUTO_DOWNLOAD_MAX_BYTES;
  }

  if (media.kind !== 'file') {
    return false;
  }

  return !networkPolicy.canAutoDownloadFiles ||
    sizeBytes <= 0 ||
    sizeBytes > CHAT_SMALL_FILE_AUTO_DOWNLOAD_MAX_BYTES ||
    sizeBytes > CHAT_MEDIA_LIMITS.file;
}

function buildChatMediaNetworkPolicy(state: NetInfoState | null): ChatMediaNetworkPolicy {
  const isConnected = state?.isConnected !== false && state?.isInternetReachable !== false;
  const isConnectionExpensive = Boolean(state?.details?.isConnectionExpensive);
  const type = state?.type || 'unknown';
  const isCellular = type === 'cellular';
  const canAutoDownloadImages = isConnected;
  const canAutoDownloadFiles = isConnected && !isCellular && !isConnectionExpensive;

  return {
    canAutoDownloadFiles,
    canAutoDownloadImages,
    isConnectionExpensive: isCellular || isConnectionExpensive,
    networkLabel: type
  };
}

function getMediaTransferLabel(media: ChatMediaAttachment): string {
  if (media.transferStatus === 'queued') {
    return 'Queued';
  }

  if (media.transferStatus === 'uploading') {
    return 'Sending';
  }

  if (media.transferStatus === 'downloading') {
    return 'Downloading';
  }

  if (media.transferStatus === 'failed') {
    return 'Failed';
  }

  return '';
}

function getMediaItemsTransferLabel(mediaItems: ChatMediaAttachment[]): string {
  if (!mediaItems.length) {
    return '';
  }

  if (mediaItems.some((media) => media.transferStatus === 'failed')) {
    return 'Failed';
  }

  if (mediaItems.some((media) => media.transferStatus === 'uploading')) {
    return 'Sending';
  }

  if (mediaItems.some((media) => media.transferStatus === 'downloading')) {
    return 'Downloading';
  }

  if (mediaItems.some((media) => media.transferStatus === 'queued')) {
    return 'Queued';
  }

  return '';
}

function getMediaItemsTransferProgress(mediaItems: ChatMediaAttachment[]): number {
  if (!mediaItems.length) {
    return 0;
  }

  const progressTotal = mediaItems.reduce((total, media) => total + Math.max(0, Math.min(media.transferProgress || 0, 1)), 0);

  return progressTotal / mediaItems.length;
}

function getMediaItemsSize(mediaItems: ChatMediaAttachment[]): number {
  return mediaItems.reduce((total, media) => total + Math.max(media.sizeBytes || 0, 0), 0);
}

function buildClearChatSummary(messages: ChatMessage[]): ClearChatSummary {
  const uniqueMessagesForSummary = uniqueChatMessages(messages);
  let mediaFileCount = 0;
  let mediaSizeBytes = 0;
  let allMediaSizeBytes = 0;
  let textSizeBytes = 0;

  uniqueMessagesForSummary.forEach((message) => {
    const mediaItems = getMessageMediaItems(message);
    const localMediaItems = mediaItems.filter(hasClearableLocalMedia);

    mediaFileCount += localMediaItems.length;
    mediaSizeBytes += getMediaItemsSize(localMediaItems);
    allMediaSizeBytes += getMediaItemsSize(mediaItems);
    textSizeBytes += getChatMessageStorageByteEstimate(message);
  });

  return {
    mediaFileCount,
    mediaSizeBytes,
    messageCount: uniqueMessagesForSummary.length,
    textSizeBytes,
    totalSizeBytes: allMediaSizeBytes + textSizeBytes
  };
}

async function clearDownloadedMediaFilesFromMessages(messages: ChatMessage[]): Promise<ChatMessage[]> {
  const uniqueMessagesForCleanup = uniqueChatMessages(messages);
  const deletableLocalUris = new Set<string>();

  uniqueMessagesForCleanup.forEach((message) => {
    getMessageMediaItems(message).forEach((media) => {
      const localUri = getDeletableLocalMediaUri(media);

      if (localUri) {
        deletableLocalUris.add(localUri);
      }
    });
  });

  await Promise.all([...deletableLocalUris].map((localUri) =>
    FileSystem.deleteAsync(localUri, { idempotent: true }).catch(() => undefined)
  ));

  return uniqueMessagesForCleanup.map(clearLocalMediaReferencesFromMessage);
}

function clearLocalMediaReferencesFromMessage(message: ChatMessage): ChatMessage {
  const mediaItems = getMessageMediaItems(message).map(clearLocalMediaReference);
  const primaryMedia = mediaItems[0] || null;

  return {
    ...message,
    image: primaryMedia?.kind === 'image' ? toChatImageAttachment(primaryMedia) : null,
    media: primaryMedia,
    mediaItems: Array.isArray(message.mediaItems) && message.mediaItems.length ? mediaItems : []
  };
}

function clearLocalMediaReference(media: ChatMediaAttachment): ChatMediaAttachment {
  const nextMedia: ChatMediaAttachment = {
    ...media,
    localUri: undefined,
    transferProgress: undefined,
    transferStatus: undefined
  };

  if (nextMedia.kind === 'image') {
    const imageAttachment: ChatImageAttachment = {
      ...toChatImageAttachment(nextMedia),
      dataUrl: undefined
    };

    return imageAttachment;
  }

  return nextMedia;
}

function getDeletableLocalMediaUri(media: ChatMediaAttachment): string {
  const localUri = typeof media.localUri === 'string' ? media.localUri.trim() : '';

  if (!localUri || localUri.startsWith('data:')) {
    return '';
  }

  const allowedPrefixes = [FileSystem.documentDirectory, FileSystem.cacheDirectory]
    .filter((prefix): prefix is string => Boolean(prefix));

  return allowedPrefixes.some((prefix) => localUri.startsWith(prefix))
    ? localUri
    : '';
}

function hasClearableLocalMedia(media: ChatMediaAttachment): boolean {
  return Boolean(getDeletableLocalMediaUri(media));
}

function getChatMessageStorageByteEstimate(message: ChatMessage): number {
  const textBytes = getUtf8ByteLength(message.text || '');
  const replyBytes = message.replyTo ? getUtf8ByteLength(message.replyTo.text || '') : 0;

  return textBytes + replyBytes + 180;
}

function getUtf8ByteLength(value: string): number {
  let bytes = 0;

  for (let index = 0; index < value.length; index += 1) {
    const codePoint = value.charCodeAt(index);

    if (codePoint <= 0x7F) {
      bytes += 1;
    } else if (codePoint <= 0x7FF) {
      bytes += 2;
    } else if (codePoint >= 0xD800 && codePoint <= 0xDBFF) {
      bytes += 4;
      index += 1;
    } else {
      bytes += 3;
    }
  }

  return bytes;
}

function toLocalChatMediaInput(media: ChatMediaAttachment): LocalChatMediaInput {
  if (!media.localUri || media.localUri.startsWith('data:')) {
    throw new Error('This media is not available on this device yet.');
  }

  return {
    contentType: media.contentType,
    durationMs: media.durationMs,
    fileName: media.fileName,
    height: media.height,
    kind: media.kind,
    thumbnailContentType: media.thumbnailContentType,
    thumbnailDataUrl: media.thumbnailDataUrl,
    thumbnailHeight: media.thumbnailHeight,
    thumbnailWidth: media.thumbnailWidth,
    sizeBytes: media.sizeBytes,
    uri: media.localUri,
    width: media.width
  };
}

async function getLocalFileSize(uri: string): Promise<number> {
  const info = await FileSystem.getInfoAsync(uri);

  return info.exists && typeof info.size === 'number' ? Math.max(info.size, 0) : 0;
}

function getVoiceNoteContentType(uri: string): string {
  const extension = getUriExtension(uri);

  if (extension === '3gp') {
    return 'audio/3gpp';
  }

  if (extension === 'webm') {
    return 'audio/webm';
  }

  if (extension === 'wav') {
    return 'audio/wav';
  }

  if (extension === 'aac') {
    return 'audio/aac';
  }

  return 'audio/mp4';
}

function buildVoiceNoteFileName(uri: string): string {
  const extension = getUriExtension(uri) || (Platform.OS === 'android' ? '3gp' : 'm4a');
  const timestamp = new Date()
    .toISOString()
    .replace(/[:.]/g, '-')
    .replace('T', '_')
    .replace('Z', '');

  return `VOICE-${timestamp}.${extension}`;
}

function getUriExtension(uri: string): string {
  return (uri.split('?')[0] || '')
    .split('.')
    .pop()
    ?.replace(/[^A-Za-z0-9]/g, '')
    .toLowerCase() || '';
}

function buildVoiceNoteWaveform(media: ChatMediaAttachment): number[] {
  const seedSource = `${media.mediaId || media.fileName || 'voice'}_${media.sizeBytes || 0}`;
  let seed = 0;

  for (let index = 0; index < seedSource.length; index += 1) {
    seed = (seed + seedSource.charCodeAt(index) * (index + 1)) % 9973;
  }

  return Array.from({ length: 36 }, (_item, index) => {
    const value = Math.sin((seed + index * 29) * 0.17) + Math.cos((seed + index * 11) * 0.09);
    const normalized = Math.abs(value) / 2;

    return Math.max(6, Math.round(8 + normalized * 20));
  });
}

function safePauseAudioPlayer(player: { pause: () => void }): void {
  try {
    player.pause();
  } catch {
    // Expo may release the native shared object before React cleanup runs.
  }
}

function safeIsAudioRecorderRecording(recorder: { getStatus: () => { isRecording?: boolean } }): boolean {
  try {
    return recorder.getStatus().isRecording === true;
  } catch {
    return false;
  }
}

async function safeStopAudioRecorder(recorder: { stop: () => Promise<void> }): Promise<void> {
  try {
    await recorder.stop();
  } catch {
    // Expo may release the native recorder before cleanup or route changes finish.
  }
}

function safePlayAudioPlayer(player: { play: () => void }): void {
  try {
    player.play();
  } catch (error) {
    throw error instanceof Error ? error : new Error('Unable to play this audio.');
  }
}

function safeReplaceAudioPlayerSource(
  player: { replace: (source: { uri: string }) => void },
  uri: string
): void {
  try {
    player.replace({ uri });
  } catch (error) {
    throw error instanceof Error ? error : new Error('Unable to load this audio.');
  }
}

function getAudioSeekSeconds(locationX: number, width: number, durationSeconds: number): number {
  if (!width || !durationSeconds) {
    return 0;
  }

  const progress = Math.min(Math.max(locationX / width, 0), 1);

  return clampAudioSeconds(durationSeconds * progress, durationSeconds);
}

function clampAudioSeconds(valueSeconds: number, durationSeconds: number): number {
  return Math.min(Math.max(valueSeconds, 0), Math.max(durationSeconds, 0));
}

function formatMediaDuration(durationMs?: number): string {
  const safeDurationMs = Number.isFinite(durationMs) ? Math.max(durationMs || 0, 0) : 0;
  const totalSeconds = Math.round(safeDurationMs / 1000);
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;

  return `${minutes}:${seconds.toString().padStart(2, '0')}`;
}

function formatAudioSeconds(valueSeconds?: number): string {
  const safeSeconds = Number.isFinite(valueSeconds) ? Math.max(Math.floor(valueSeconds || 0), 0) : 0;
  const minutes = Math.floor(safeSeconds / 60);
  const seconds = safeSeconds % 60;

  return `${minutes}:${seconds.toString().padStart(2, '0')}`;
}

function formatByteCount(sizeBytes?: number): string {
  const safeSize = Number.isFinite(sizeBytes) ? Math.max(sizeBytes || 0, 0) : 0;

  if (safeSize >= 1024 * 1024) {
    return `${(safeSize / (1024 * 1024)).toFixed(safeSize >= 10 * 1024 * 1024 ? 0 : 1)} MB`;
  }

  if (safeSize >= 1024) {
    return `${Math.round(safeSize / 1024)} KB`;
  }

  return `${Math.round(safeSize)} B`;
}

function formatAttachmentMeta(media: ChatMediaAttachment): string {
  const typeLabel = media.kind === 'audio'
    ? 'Voice note'
    : media.kind === 'video'
      ? 'Video'
      : getReadableFileExtension(media.fileName) || (isAudioAttachment(media) ? 'Audio' : 'File');

  return `${typeLabel} • ${formatByteCount(media.sizeBytes)}`;
}

function getReadableFileExtension(fileName?: string | null): string {
  const safeFileName = typeof fileName === 'string' ? fileName : '';
  const extension = safeFileName.split('.').pop()?.replace(/[^A-Za-z0-9]/g, '').toUpperCase();

  return extension && extension !== safeFileName.toUpperCase() ? extension : '';
}

function getChatMessagePreview(message: ChatMessage): string {
  const text = getChatMessageTextPreview(message);

  if (text) {
    return text;
  }

  const mediaItems = getMessageMediaItems(message);

  if (mediaItems.length > 1) {
    return `${mediaItems.length} items`;
  }

  const media = mediaItems[0] || getMessageMedia(message);

  if (!media) {
    return '';
  }

  if (media.kind === 'image') {
    return 'Photo';
  }

  if (media.kind === 'video') {
    return 'Video';
  }

  if (media.kind === 'audio') {
    return 'Voice message';
  }

  return media.fileName || 'File';
}

function getChatMessageTextPreview(message: ChatMessage): string {
  return (message.text || '').replace(/\s+/g, ' ').trim();
}

function formatReplyPreviewText(text: string): string {
  return text
    .replace(/\s+/g, ' ')
    .trim() || 'Message';
}

function buildMessageThreadItems(messages: ChatMessage[]): MessageThreadItem[] {
  const items: MessageThreadItem[] = [];
  let activeDateKey = '';

  messages.forEach((message) => {
    const nextDateKey = getMessageDateKey(message.sentAt);

    if (nextDateKey && nextDateKey !== activeDateKey) {
      activeDateKey = nextDateKey;
      items.push({
        id: `date-${nextDateKey}`,
        label: formatMessageDate(message.sentAt),
        type: 'date'
      });
    }

    items.push({
      id: `message-${message.messageId}`,
      message,
      type: 'message'
    });
  });

  return items;
}

function getMessageDateKey(value: string): string {
  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return '';
  }

  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');

  return `${year}-${month}-${day}`;
}

function formatMessageDate(value: string): string {
  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return '';
  }

  return date.toLocaleDateString([], {
    day: 'numeric',
    month: 'short',
    weekday: 'short',
    year: 'numeric'
  });
}

function formatMessageDateTime(value: string): string {
  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return '';
  }

  return `${date.toLocaleDateString([], {
    day: 'numeric',
    month: 'short',
    year: '2-digit'
  })}, ${date.toLocaleTimeString([], {
    hour: 'numeric',
    minute: '2-digit'
  })}`;
}

function formatCompactCount(value: number): string {
  const safeValue = Math.max(0, Math.floor(value));

  if (safeValue > 99) {
    return '99+';
  }

  return String(safeValue);
}

async function cacheCurrentUserProfilePhoto(
  profile: CurrentUserProfile,
  idToken: string
): Promise<CurrentUserProfile> {
  const cachedPhotoUri = await getCachedProfilePhotoUri({
    cacheKey: profile.profilePhotoCacheKey,
    idToken,
    profilePhotoUrl: profile.profilePhotoUrl
  });

  return {
    ...profile,
    profilePhotoUrl: cachedPhotoUri
  };
}

async function cacheApprovedEmployeePhotos(
  employees: ApprovedEmployee[],
  idToken: string
): Promise<ApprovedEmployee[]> {
  return Promise.all(employees.map(async (employee) => ({
    ...employee,
    profilePhotoUrl: await getCachedProfilePhotoUri({
      cacheKey: employee.profilePhotoCacheKey,
      idToken,
      profilePhotoUrl: employee.profilePhotoUrl
    })
  })));
}

async function cacheChatContactPhotos(
  contacts: ChatContact[],
  idToken: string
): Promise<ChatContact[]> {
  return Promise.all(contacts.map((contact) => cacheChatContactPhoto(contact, idToken)));
}

async function cacheChatContactPhoto(
  contact: ChatContact,
  idToken: string
): Promise<ChatContact> {
  const [profilePhotoUrl, members] = await Promise.all([
    getCachedProfilePhotoUri({
      cacheKey: contact.profilePhotoCacheKey,
      idToken,
      profilePhotoUrl: contact.profilePhotoUrl
    }),
    contact.members
      ? cacheChatGroupMemberPhotos(contact.members, idToken)
      : Promise.resolve(contact.members)
  ]);

  return {
    ...contact,
    members,
    profilePhotoUrl
  };
}

async function cacheChatGroupMemberPhotos(
  members: ChatGroupMember[],
  idToken: string
): Promise<ChatGroupMember[]> {
  return Promise.all(members.map(async (member) => ({
    ...member,
    profilePhotoUrl: await getCachedProfilePhotoUri({
      cacheKey: member.profilePhotoCacheKey,
      idToken,
      profilePhotoUrl: member.profilePhotoUrl
    })
  })));
}

function mapApprovedEmployeeToListItem(
  employee: ApprovedEmployee,
  phoneDisplayOverride?: string
): EmployeeListItem {
  const phoneDisplay = getApprovedEmployeePhoneDisplay(employee, phoneDisplayOverride);
  const displayName = employee.displayName?.trim() || '';
  const hasRealDisplayName = Boolean(displayName && !isMaskedPhoneLabel(displayName));
  const name = hasRealDisplayName ? displayName : phoneDisplay;
  const baseRole = employee.role || 'EMPLOYEE';

  return {
    baseRole,
    department: employee.departmentName,
    id: employee.approvedPhoneId,
    initials: getInitials(name),
    isPhoneOnly: !hasRealDisplayName,
    name,
    phoneFormatted: phoneDisplay,
    profilePhotoUrl: employee.profilePhotoUrl,
    role: baseRole === 'DEPT_ADMIN' ? `${employee.roleName} · Dept admin` : employee.roleName,
    roleId: employee.roleId,
    status: formatEmployeeStatus(employee.status),
    statusValue: employee.status
  };
}

function getApprovedEmployeeDisplayLabel(
  employee: ApprovedEmployee,
  phoneDisplayOverride?: string
): string {
  const phoneDisplay = getApprovedEmployeePhoneDisplay(employee, phoneDisplayOverride);
  const displayName = employee.displayName?.trim() || '';

  return displayName && !isMaskedPhoneLabel(displayName) ? displayName : phoneDisplay;
}

function getApprovedEmployeePhoneDisplay(
  employee: ApprovedEmployee,
  phoneDisplayOverride?: string
): string {
  return phoneDisplayOverride ||
    employee.phoneFormatted ||
    employee.phoneMasked ||
    'Phone number';
}

function buildInvitedEmployeePhoneDisplayMap(
  employees: ApprovedEmployee[],
  contacts: InviteContactDraft[]
): Record<string, string> {
  const usedContactIndexes = new Set<number>();
  const phoneDisplayByEmployeeId: Record<string, string> = {};

  employees.forEach((employee) => {
    const matchingContactIndex = contacts.findIndex((contact, index) => {
      if (usedContactIndexes.has(index)) {
        return false;
      }

      const formattedPhoneNumber = formatPhoneNumberForInviteDisplay(contact.phoneNumber);

      return (
        formattedPhoneNumber === employee.phoneFormatted ||
        maskLocalPhoneNumber(contact.phoneNumber) === employee.phoneMasked ||
        getPhoneLastFourDigits(contact.phoneNumber) === employee.phoneLast4
      );
    });

    if (matchingContactIndex < 0) {
      return;
    }

    usedContactIndexes.add(matchingContactIndex);
    phoneDisplayByEmployeeId[employee.approvedPhoneId] = formatPhoneNumberForInviteDisplay(
      contacts[matchingContactIndex].phoneNumber
    );
  });

  return phoneDisplayByEmployeeId;
}

function isMaskedPhoneLabel(value: string): boolean {
  return value.includes('*');
}

function mapChatContactToChatItem(contact: ChatContact): ChatItem {
  const visibleContact = applyClearedChatVisibility(contact);

  return {
    chatType: visibleContact.chatType === 'GROUP' ? 'GROUP' : 'DIRECT',
    clearedAt: visibleContact.clearedAt || null,
    contactId: visibleContact.contactId,
    conversationId: visibleContact.conversationId,
    hasActiveDevice: visibleContact.hasActiveDevice,
    id: `${visibleContact.chatType === 'GROUP' ? 'group' : 'contact'}-${visibleContact.contactId}`,
    initials: visibleContact.initials,
    isArchived: visibleContact.isArchived === true,
    isDepartmentDefault: visibleContact.isDepartmentDefault === true,
    isFavorite: visibleContact.isFavorite === true,
    isSpam: visibleContact.isSpam === true,
    isOnline: visibleContact.isOnline === true,
    lastMessageAt: visibleContact.lastMessageAt,
    lastSeenAt: visibleContact.lastSeenAt,
    memberCount: visibleContact.memberCount,
    members: visibleContact.members,
    memberPolicy: visibleContact.memberPolicy,
    phoneMasked: visibleContact.phoneMasked || null,
    profilePhotoCacheKey: visibleContact.profilePhotoCacheKey,
    preview: visibleContact.preview || '',
    profilePhotoUrl: visibleContact.profilePhotoUrl,
    role: visibleContact.role,
    roleName: visibleContact.roleName,
    spammedAt: visibleContact.spammedAt || null,
    status: visibleContact.status,
    title: visibleContact.displayName,
    trashSegments: visibleContact.trashSegments || [],
    unreadCount: visibleContact.unreadCount || 0
  };
}

function mapChatItemToChatContact(chat: ChatItem): ChatContact {
  return {
    chatType: chat.chatType,
    clearedAt: chat.clearedAt || null,
    contactId: chat.contactId,
    conversationId: chat.conversationId,
    displayName: chat.title,
    hasActiveDevice: chat.hasActiveDevice,
    initials: chat.initials || getInitials(chat.title),
    isArchived: chat.isArchived === true,
    isDepartmentDefault: chat.isDepartmentDefault === true,
    isFavorite: chat.isFavorite === true,
    isSpam: chat.isSpam === true,
    isOnline: chat.isOnline === true,
    lastMessageAt: chat.lastMessageAt,
    lastSeenAt: chat.lastSeenAt,
    memberCount: chat.memberCount,
    members: chat.members,
    memberPolicy: chat.memberPolicy,
    phoneMasked: chat.phoneMasked || null,
    preview: chat.preview || '',
    profilePhotoCacheKey: chat.profilePhotoCacheKey || null,
    profilePhotoUrl: chat.profilePhotoUrl || null,
    role: chat.role || 'EMPLOYEE',
    roleName: chat.roleName || '',
    spammedAt: chat.spammedAt || null,
    status: chat.status || 'ACTIVE',
    trashSegments: chat.trashSegments || [],
    unreadCount: chat.unreadCount || 0
  };
}

function getCommonGroupContactsForDirectChat(
  chat: ChatItem | null,
  groupContacts: ChatContact[]
): ChatContact[] {
  if (!chat || chat.chatType === 'GROUP') {
    return [];
  }

  return groupContacts.filter((groupContact) =>
    (groupContact.members || []).some((member) => member.uid === chat.contactId)
  );
}

function getAddableContactsForGroup(
  chat: ChatItem,
  directContacts: ChatContact[],
  currentUid: string
): ChatContact[] {
  const existingMemberIds = new Set((chat.members || [])
    .map((member) => member.uid)
    .filter(Boolean));

  existingMemberIds.add(currentUid);

  return directContacts.filter((contact) => !existingMemberIds.has(contact.contactId));
}

function filterGroupInfoMembers(
  members: ChatGroupMember[],
  directContactById: Map<string, ChatContact>,
  currentUid: string,
  search: string
): ChatGroupMember[] {
  const query = normalizeSearchQuery(search);

  if (!query) {
    return members;
  }

  return members.filter((member) => {
    const directContact = directContactById.get(member.uid);
    const displayName = member.uid === currentUid ? 'You' : member.displayName;

    return normalizeSearchQuery([
      displayName,
      member.roleName,
      directContact?.phoneMasked || ''
    ].join(' ')).includes(query);
  });
}

function mapGroupMembersToSelectableContacts(
  members: ChatGroupMember[],
  directContacts: ChatContact[],
  currentUid: string
): ChatContact[] {
  const directContactById = new Map(directContacts.map((contact) => [contact.contactId, contact]));

  return members
    .filter((member) => member.uid && member.uid !== currentUid)
    .map((member) => {
      const directContact = directContactById.get(member.uid);
      const isOnline = directContact?.isOnline === true;

      return {
        chatType: 'DIRECT',
        contactId: member.uid,
        conversationId: directContact?.conversationId || member.uid,
        displayName: member.displayName,
        hasActiveDevice: directContact?.hasActiveDevice !== false,
        initials: member.initials,
        isOnline,
        lastMessageAt: null,
        lastSeenAt: directContact?.lastSeenAt || null,
        phoneMasked: directContact?.phoneMasked || null,
        preview: '',
        profilePhotoCacheKey: member.profilePhotoCacheKey || directContact?.profilePhotoCacheKey || null,
        profilePhotoUrl: member.profilePhotoUrl || directContact?.profilePhotoUrl || null,
        role: member.role,
        roleName: isOnline ? 'online' : member.roleName,
        status: 'ACTIVE',
        unreadCount: 0
      };
    });
}

function getOnlineGroupMemberCount(
  chat: ChatItem,
  directContacts: ChatContact[],
  currentUid: string
): number {
  if (chat.chatType !== 'GROUP') {
    return chat.isOnline ? 1 : 0;
  }

  const directContactById = new Map(directContacts.map((contact) => [contact.contactId, contact]));

  return (chat.members || []).filter((member) =>
    member.uid !== currentUid &&
    directContactById.get(member.uid)?.isOnline === true
  ).length;
}

function formatGroupOnlineCount(onlineCount: number): string {
  return onlineCount === 1 ? '1 online' : `${Math.max(onlineCount, 0)} online`;
}

function formatGroupMemberCount(memberCount: number): string {
  const safeMemberCount = Math.max(Math.round(memberCount || 0), 0);

  return safeMemberCount === 1 ? '1 member' : `${safeMemberCount} members`;
}

function formatStarredMessageCount(starredCount: number): string {
  const safeStarredCount = Math.max(Math.round(starredCount || 0), 0);

  return safeStarredCount === 0
    ? 'None'
    : `${safeStarredCount} ${safeStarredCount === 1 ? 'message' : 'messages'}`;
}

function formatCommonGroupCount(groupCount: number): string {
  const safeGroupCount = Math.max(Math.round(groupCount || 0), 0);

  return safeGroupCount === 1 ? '1 group in common' : `${safeGroupCount} groups in common`;
}

function getContactInfoPresenceText(chat: ChatItem): string {
  if (chat.isOnline) {
    return 'online';
  }

  if (chat.lastSeenAt) {
    const lastSeen = formatChatListTime(chat.lastSeenAt);

    if (lastSeen) {
      return `last seen ${lastSeen}`;
    }
  }

  return chat.roleName || 'Synzapp contact';
}

function getDefaultChatNotificationSettings(contactId: string): ChatNotificationSettings {
  return {
    alertTone: 'default',
    contactId,
    muteMode: 'off',
    mutedUntil: null,
    updatedAt: null
  };
}

function getOptimisticMutedUntil(muteMode: ChatNotificationMuteMode): string | null {
  if (muteMode === 'off' || muteMode === 'always') {
    return null;
  }

  const durationMs = muteMode === '8h'
    ? 8 * 60 * 60 * 1000
    : 7 * 24 * 60 * 60 * 1000;

  return new Date(Date.now() + durationMs).toISOString();
}

function getChatNotificationSummary(settings: ChatNotificationSettings | null): string {
  if (!settings || settings.muteMode === 'off') {
    return 'All';
  }

  return `Muted ${getChatNotificationMuteLabel(settings).toLowerCase()}`;
}

function getChatNotificationMuteLabel(settings: ChatNotificationSettings): string {
  if (settings.muteMode === 'always') {
    return 'Always';
  }

  if (settings.muteMode === '8h' && settings.mutedUntil) {
    return '8 hours';
  }

  if (settings.muteMode === '1w' && settings.mutedUntil) {
    return '1 week';
  }

  return 'No';
}

function getChatNotificationAlertToneLabel(alertTone: ChatNotificationAlertTone): string {
  return chatNotificationAlertToneOptions.find((option) => option.value === alertTone)?.label || 'Default (Note)';
}

function getDefaultChatTranscriptLanguage(contactId: string): ChatTranscriptLanguageSetting {
  return {
    contactId,
    languageCode: 'en-US',
    updatedAt: null
  };
}

function getChatTranscriptLanguageLabel(languageCode: ChatTranscriptLanguageCode): string {
  return chatTranscriptLanguageOptions.find((option) => option.code === languageCode)?.label ||
    'English (United States)';
}

function filterTranscriptLanguageOptions(
  languages: TranscriptLanguageOption[],
  search: string
): TranscriptLanguageOption[] {
  const query = normalizeSearchQuery(search);

  if (!query) {
    return languages;
  }

  return languages.filter((language) =>
    normalizeSearchQuery(`${language.label} ${language.code}`).includes(query)
  );
}

function getCommonGroupPreview(group: ChatContact, contactName: string): string {
  const memberNames = (group.members || [])
    .map((member) => member.displayName)
    .filter((name) => name && name !== contactName)
    .slice(0, 4);

  if (!memberNames.length) {
    return getGroupSubtitleFromContact(group);
  }

  return memberNames.join(', ');
}

function getGroupSubtitleFromContact(group: ChatContact): string {
  if (group.isDepartmentDefault) {
    return 'Department group';
  }

  return group.memberCount === 1 ? '1 member' : `${group.memberCount || 0} members`;
}

function getGroupInfoDescription(chat: ChatItem): string {
  if (chat.isDepartmentDefault) {
    return chat.title;
  }

  if (chat.memberPolicy === 'DEPARTMENT_PLUS_EXPLICIT') {
    return 'Department group';
  }

  return 'Company group';
}

function canExitGroupChat(chat: ChatItem): boolean {
  return chat.chatType === 'GROUP' &&
    chat.isDepartmentDefault !== true &&
    chat.memberPolicy !== 'DEPARTMENT_PLUS_EXPLICIT';
}

function canCurrentUserChangeGroupPhoto(
  chat: ChatItem | null,
  profile: CurrentUserProfile | null
): boolean {
  if (!chat || chat.chatType !== 'GROUP' || !profile) {
    return false;
  }

  const isDepartmentGroup = chat.isDepartmentDefault === true ||
    chat.memberPolicy === 'DEPARTMENT_PLUS_EXPLICIT';

  if (isDepartmentGroup) {
    return profile.role === 'ORG_ADMIN' || profile.role === 'DEPT_ADMIN';
  }

  return true;
}

function getGroupInfoMemberSubtitle(
  member: ChatGroupMember,
  directContact: ChatContact | undefined,
  isCurrentUser: boolean
): string {
  if (isCurrentUser) {
    return member.roleName || 'Member';
  }

  if (directContact?.isOnline) {
    return 'online';
  }

  return member.roleName || 'Member';
}

function getGroupInfoMemberBadge(member: ChatGroupMember): string {
  if (member.role === 'ORG_ADMIN' || member.role === 'DEPT_ADMIN') {
    return 'Admin';
  }

  return '';
}

function getGroupCallPeopleTitle(mode: GroupCallMode): string {
  if (mode === 'voice') {
    return 'Voice call';
  }

  if (mode === 'video') {
    return 'Video call';
  }

  return 'Select people';
}

function applyChatListFilter(chats: ChatItem[], filter: ChatListFilter): ChatItem[] {
  if (filter === 'archived') {
    return chats;
  }

  if (filter === 'unread') {
    return chats.filter((chat) => (chat.unreadCount || 0) > 0);
  }

  if (filter === 'groups') {
    return chats.filter((chat) => chat.chatType === 'GROUP');
  }

  if (filter === 'favorites') {
    return chats.filter((chat) => isFavoriteChat(chat));
  }

  return chats;
}

function shouldShowActiveChatInList(chat: ChatItem): boolean {
  return Boolean(
    chat.isSpam !== true && (
      chat.clearedAt ||
      chat.lastMessageAt ||
      chat.preview.trim() ||
      chat.unreadCount > 0
    )
  );
}

function hasChatKnownMessages(chat: ChatItem): boolean {
  return Boolean(chat.lastMessageAt || chat.preview.trim() || chat.unreadCount > 0);
}

function shouldShowTrashChatInList(chat: ChatItem): boolean {
  return chat.isSpam === true || getActiveTrashSegments(chat).length > 0;
}

function getActiveTrashSegments(chat: Pick<ChatItem, 'spammedAt' | 'trashSegments'>): ChatTrashSegment[] {
  const nowMs = Date.now();
  const activeSegments = (chat.trashSegments || []).filter((segment) => segment.expiresAtMs > nowMs);

  if (activeSegments.length) {
    return activeSegments.sort((first, second) => second.deletedAtMs - first.deletedAtMs);
  }

  if (!chat.spammedAt) {
    return [];
  }

  const deletedAtMs = Date.parse(chat.spammedAt);

  if (!Number.isFinite(deletedAtMs)) {
    return [];
  }

  const expiresAtMs = deletedAtMs + 30 * 24 * 60 * 60 * 1000;

  if (expiresAtMs <= nowMs) {
    return [];
  }

  return [{
    deletedAt: new Date(deletedAtMs).toISOString(),
    deletedAtMs,
    endAtMs: null,
    expiresAt: new Date(expiresAtMs).toISOString(),
    expiresAtMs,
    segmentId: '',
    startAtMs: null
  }];
}

function getChatListPreviewText(chat: ChatItem): string {
  if (isChatItemClearedThroughLastMessage(chat)) {
    return '';
  }

  const preview = chat.preview.trim();

  if (preview) {
    return preview;
  }

  return chat.lastMessageAt ? 'Message' : '';
}

function getTrashRowSubtitle(chat: ChatItem): string {
  const segments = getActiveTrashSegments(chat);
  const segmentCount = Math.max(segments.length, chat.isSpam ? 1 : 0);
  const latestSegment = segments[0] || null;
  const countLabel = segmentCount === 1 ? '1 deleted chat' : `${segmentCount} deleted chats`;
  const expiryLabel = latestSegment ? getTrashExpiryLabel(latestSegment.expiresAtMs) : 'Deletes after 30 days';

  return `${countLabel} · ${expiryLabel}`;
}

function getTrashExpiryLabel(expiresAtMs: number): string {
  const remainingMs = expiresAtMs - Date.now();

  if (remainingMs <= 0) {
    return 'Deletes soon';
  }

  const remainingDays = Math.max(1, Math.ceil(remainingMs / (24 * 60 * 60 * 1000)));

  return remainingDays === 1 ? 'Deletes in 1 day' : `Deletes in ${remainingDays} days`;
}

function formatTrashSegmentTitle(segment: ChatTrashSegment, index: number): string {
  const deletedDate = new Date(segment.deletedAtMs);
  const dateLabel = Number.isFinite(deletedDate.getTime())
    ? formatChatListTime(deletedDate.toISOString())
    : `Deleted history ${index + 1}`;

  return `Deleted ${dateLabel}`;
}

function isFavoriteChat(chat: ChatItem): boolean {
  return chat.isFavorite === true;
}

function canUseChatListActions(chat: ChatItem): boolean {
  if (chat.chatType !== 'GROUP') {
    return true;
  }

  return chat.isDepartmentDefault !== true &&
    chat.memberPolicy !== 'DEPARTMENT_PLUS_EXPLICIT';
}

function filterChatItems(chats: ChatItem[], search: string): ChatItem[] {
  const query = normalizeSearchQuery(search);

  if (!query) {
    return chats;
  }

  return chats.filter((chat) =>
    normalizeSearchQuery(`${chat.title} ${chat.preview}`).includes(query)
  );
}

function filterChatContacts(contacts: ChatContact[], search: string): ChatContact[] {
  const query = normalizeSearchQuery(search);

  if (!query) {
    return contacts;
  }

  return contacts.filter((contact) =>
    normalizeSearchQuery(`${contact.displayName} ${contact.roleName} ${contact.phoneMasked || ''}`).includes(query)
  );
}

function filterAddableChatGroups(groups: AddableChatGroup[], search: string): AddableChatGroup[] {
  const query = normalizeSearchQuery(search);

  if (!query) {
    return groups;
  }

  return groups.filter((group) =>
    normalizeSearchQuery(`${group.name} ${group.departmentName || ''} ${group.description || ''}`).includes(query)
  );
}

function filterMessageListModalMessages(
  messages: ChatMessage[],
  mode: MessageListModalMode,
  search: string,
  starredMessageIds: Record<string, boolean>
): ChatMessage[] {
  const baseMessages = mode === 'starred'
    ? messages.filter((message) => Boolean(starredMessageIds[message.messageId]))
    : messages;
  const query = normalizeSearchQuery(search);

  if (mode === 'starred' || !query) {
    return [...baseMessages].reverse();
  }

  return baseMessages
    .filter((message) => normalizeSearchQuery(getMessageListPreview(message)).includes(query))
    .reverse();
}

function getChatSearchMatches({
  dateKey,
  messages,
  query,
  senderUid
}: {
  dateKey: string | null;
  messages: ChatMessage[];
  query: string;
  senderUid: string | null;
}): ChatSearchMatch[] {
  const normalizedQuery = normalizeSearchQuery(query);

  if (!normalizedQuery && !dateKey && !senderUid) {
    return [];
  }

  return uniqueChatMessages(messages)
    .filter((message) => {
      if (senderUid && message.senderUid !== senderUid) {
        return false;
      }

      if (dateKey && getMessageDateKey(message.sentAt) !== dateKey) {
        return false;
      }

      if (normalizedQuery && !normalizeSearchQuery(message.text).includes(normalizedQuery)) {
        return false;
      }

      return true;
    })
    .map((message) => ({
      messageId: message.messageId,
      preview: getMessageListPreview(message),
      senderUid: message.senderUid,
      sentAt: message.sentAt
    }));
}

function getChatSearchMessagesForDate(messages: ChatMessage[], dateKey: string): ChatMessage[] {
  return uniqueChatMessages(messages).filter((message) => getMessageDateKey(message.sentAt) === dateKey);
}

function getLatestMessageDateKey(messages: ChatMessage[]): string {
  const latestMessage = uniqueChatMessages(messages).at(-1);

  return latestMessage ? getMessageDateKey(latestMessage.sentAt) : '';
}

function getDateFromDateKey(dateKey: string): Date {
  const [rawYear, rawMonth, rawDay] = dateKey.split('-').map((part) => Number.parseInt(part, 10));
  const fallbackDate = new Date();
  const year = Number.isFinite(rawYear) && rawYear > 0 ? rawYear : fallbackDate.getFullYear();
  const month = Number.isFinite(rawMonth) && rawMonth >= 1 && rawMonth <= 12
    ? rawMonth - 1
    : fallbackDate.getMonth();
  const day = Number.isFinite(rawDay) && rawDay >= 1
    ? Math.min(rawDay, new Date(year, month + 1, 0).getDate())
    : fallbackDate.getDate();

  return new Date(year, month, day, 12);
}

function normalizeChatSearchPickerDate(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate(), 12);
}

function getMessageDateKeyFromDate(date: Date): string {
  return buildDateKey(date.getFullYear(), date.getMonth(), date.getDate());
}

function formatChatSearchPickerDate(date: Date): string {
  return date.toLocaleDateString([], {
    day: 'numeric',
    month: 'long',
    year: 'numeric'
  });
}

function buildDateKey(year: number, month: number, day: number): string {
  return [
    String(year).padStart(4, '0'),
    String(month + 1).padStart(2, '0'),
    String(day).padStart(2, '0')
  ].join('-');
}

function getMessageListPreview(message: ChatMessage): string {
  if (message.text?.trim()) {
    return message.text.trim();
  }

  const firstMedia = message.mediaItems?.[0] || message.media || message.image || null;

  if (firstMedia) {
    if (firstMedia.kind === 'image') {
      return 'Photo';
    }

    if (firstMedia.kind === 'video') {
      return 'Video';
    }

    if (firstMedia.kind === 'audio') {
      return 'Voice message';
    }

    return firstMedia.fileName || 'File';
  }

  return 'Message';
}

function getChatSearchResultLabel({
  hasFilters,
  matchCount,
  matchIndex
}: {
  hasFilters: boolean;
  matchCount: number;
  matchIndex: number;
}): string {
  if (!hasFilters) {
    return 'Type, choose a date, or pick a person';
  }

  if (!matchCount) {
    return 'No results';
  }

  return `${matchIndex + 1} of ${matchCount}`;
}

function formatChatSearchDateLabel(dateKey: string): string {
  const [year, month, day] = dateKey.split('-').map((part) => Number.parseInt(part, 10));
  const date = new Date(year || 0, Math.max((month || 1) - 1, 0), day || 1);

  if (Number.isNaN(date.getTime())) {
    return 'Date';
  }

  return date.toLocaleDateString([], {
    day: 'numeric',
    month: 'short',
    year: 'numeric'
  });
}

function getGroupMessageSenderName(
  message: ChatMessage,
  currentUid: string,
  senderNameByUid: Map<string, string>
): string {
  if (message.senderUid === currentUid) {
    return 'You';
  }

  return senderNameByUid.get(message.senderUid) || 'Member';
}

function getChatSearchSenderLabel(
  senderUid: string,
  currentUid: string,
  senderNameByUid: Map<string, ChatGroupMember>
): string {
  if (senderUid === currentUid) {
    return 'You';
  }

  return senderNameByUid.get(senderUid)?.displayName || 'Member';
}

function renderHighlightedMessageText(text: string, query: string): React.ReactNode {
  const safeQuery = query.trim();

  if (!safeQuery) {
    return text;
  }

  const lowerText = text.toLowerCase();
  const lowerQuery = safeQuery.toLowerCase();
  const parts: React.ReactNode[] = [];
  let cursor = 0;
  let partIndex = 0;

  while (cursor < text.length) {
    const matchIndex = lowerText.indexOf(lowerQuery, cursor);

    if (matchIndex < 0) {
      parts.push(text.slice(cursor));
      break;
    }

    if (matchIndex > cursor) {
      parts.push(text.slice(cursor, matchIndex));
    }

    parts.push(
      <Text key={`highlight-${partIndex}`} style={styles.messageSearchHighlight}>
        {text.slice(matchIndex, matchIndex + safeQuery.length)}
      </Text>
    );

    cursor = matchIndex + safeQuery.length;
    partIndex += 1;
  }

  return parts;
}

function normalizeSearchQuery(value: string): string {
  return value.trim().toLowerCase();
}

function getFullScreenModalTopPadding(topInset: number): number {
  const androidStatusBarHeight = Platform.OS === 'android' ? RNStatusBar.currentHeight || 0 : 0;
  const deviceTopInset = Math.max(topInset, androidStatusBarHeight);

  return Platform.OS === 'android'
    ? Math.max(deviceTopInset + 10, 38)
    : Math.max(deviceTopInset + 8, 22);
}

function getKeyboardDismissMode(): 'interactive' | 'on-drag' {
  return Platform.OS === 'ios' ? 'interactive' : 'on-drag';
}

function getAiPetalColor(index: number): string {
  const colorsByIndex = ['#6754F5', '#7C3AED', '#A855F7', '#2F6BFF', '#20C997', '#4F46E5'];

  return colorsByIndex[index % colorsByIndex.length];
}

function getNativeFullHeightModalPresentationStyle(): 'fullScreen' | 'pageSheet' {
  return Platform.OS === 'ios' ? 'pageSheet' : 'fullScreen';
}

function applyLocalChatPreview(contact: ChatContact, messages: ChatMessage[]): ChatContact {
  const visibleContact = applyClearedChatVisibility(contact);
  const localMessages = uniqueChatMessages(messages).filter((message) =>
    !isMessageHiddenByContactClear(visibleContact, message)
  );
  const latestMessage = localMessages.at(-1);
  const latestPreview = latestMessage ? getMessageListPreview(latestMessage) : '';

  if (!latestMessage && !latestPreview) {
    return visibleContact;
  }

  const lastMessageAt = latestMessage &&
    (!visibleContact.lastMessageAt || latestMessage.sentAt > visibleContact.lastMessageAt)
    ? latestMessage.sentAt
    : visibleContact.lastMessageAt;

  return {
    ...visibleContact,
    lastMessageAt,
    preview: latestPreview || visibleContact.preview
  };
}

function buildLocalChatContactsFromCachedConversations(
  cachedConversations: LocalConversationRecord[],
  pendingMessages: PendingChatMessage[],
  allowedCachedGroupContactIds: Set<string>
): ChatContact[] {
  const cachedContacts = cachedConversations
    .map((conversation) => conversation.contact)
    .filter((contact): contact is ChatContact => {
      if (!contact?.contactId) {
        return false;
      }

      return (contact.chatType || 'DIRECT') !== 'GROUP' || allowedCachedGroupContactIds.has(contact.contactId);
    });

  if (!cachedContacts.length) {
    return [];
  }

  return applyLocalChatPreviewsToContacts(cachedContacts, cachedConversations, pendingMessages);
}

function applyLocalChatPreviewsToContacts(
  contacts: ChatContact[],
  cachedConversations: LocalConversationRecord[],
  pendingMessages: PendingChatMessage[]
): ChatContact[] {
  const cachedConversationByContactId = new Map<string, LocalConversationRecord>();
  const pendingMessagesByContactId = new Map<string, ChatMessage[]>();

  cachedConversations.forEach((conversation) => {
    cachedConversationByContactId.set(conversation.contactId, conversation);
  });

  pendingMessages.forEach((pendingMessage) => {
    const currentMessages = pendingMessagesByContactId.get(pendingMessage.contactId) || [];

    pendingMessagesByContactId.set(pendingMessage.contactId, [...currentMessages, pendingMessage.message]);
  });

  return sortChatContacts(contacts.map((contact) => {
    const cachedConversation = cachedConversationByContactId.get(contact.contactId);
    const localMessages = [
      ...(cachedConversation?.messages || []),
      ...(pendingMessagesByContactId.get(contact.contactId) || [])
    ];

    return applyLocalChatPreview(contact, localMessages);
  }));
}

function mergeLoadedChatContactsWithVisibleState(
  currentContacts: ChatContact[],
  loadedContacts: ChatContact[],
  options: { preserveMissing?: boolean } = {}
): ChatContact[] {
  const currentContactById = new Map(currentContacts.map((contact) => [contact.contactId, contact]));
  const nextContactById = options.preserveMissing === false
    ? new Map<string, ChatContact>()
    : new Map(currentContactById);

  loadedContacts.forEach((loadedContact) => {
    const currentContact = currentContactById.get(loadedContact.contactId);

    nextContactById.set(
      loadedContact.contactId,
      mergeChatContactVisibleState(currentContact, loadedContact)
    );
  });

  return sortChatContacts([...nextContactById.values()]);
}

function mergeChatContactVisibleState(
  currentContact: ChatContact | undefined,
  nextContact: ChatContact
): ChatContact {
  const currentVisibleContact = currentContact ? applyClearedChatVisibility(currentContact) : undefined;
  const mergedContact = applyClearedChatVisibility(mergeChatContactCachedPhoto(currentVisibleContact, nextContact));

  if (!currentVisibleContact) {
    return mergedContact;
  }

  if (isChatContactClearedThroughLastMessage(mergedContact)) {
    return mergedContact;
  }

  if (
    isChatContactClearedThroughLastMessage(currentVisibleContact) &&
    isNextContactStillCoveredByClear(currentVisibleContact, mergedContact)
  ) {
    return {
      ...mergedContact,
      clearedAt: currentVisibleContact.clearedAt || mergedContact.clearedAt,
      lastMessageAt: null,
      preview: '',
      unreadCount: 0
    };
  }

  const currentPreview = currentVisibleContact.preview?.trim() || '';
  const nextPreview = mergedContact.preview?.trim() || '';

  if (
    currentVisibleContact.lastMessageAt &&
    (!mergedContact.lastMessageAt || currentVisibleContact.lastMessageAt > mergedContact.lastMessageAt)
  ) {
    return {
      ...mergedContact,
      lastMessageAt: currentVisibleContact.lastMessageAt,
      preview: currentVisibleContact.preview,
      unreadCount: currentVisibleContact.unreadCount
    };
  }

  if (
    currentPreview &&
    currentVisibleContact.lastMessageAt &&
    mergedContact.lastMessageAt &&
    currentVisibleContact.lastMessageAt >= mergedContact.lastMessageAt
  ) {
    return {
      ...mergedContact,
      preview: currentVisibleContact.preview
    };
  }

  if (!currentPreview) {
    return mergedContact;
  }

  if (!nextPreview) {
    return {
      ...mergedContact,
      preview: currentVisibleContact.preview
    };
  }

  return mergedContact;
}

function applyClearedChatVisibility(contact: ChatContact): ChatContact {
  if (!isChatContactClearedThroughLastMessage(contact)) {
    return contact;
  }

  return {
    ...contact,
    lastMessageAt: null,
    preview: '',
    unreadCount: 0
  };
}

function isChatContactClearedThroughLastMessage(contact: Pick<ChatContact, 'clearedAt' | 'lastMessageAt'>): boolean {
  return isClearedThroughTimestamp(contact.clearedAt || null, contact.lastMessageAt || null);
}

function isChatItemClearedThroughLastMessage(chat: Pick<ChatItem, 'clearedAt' | 'lastMessageAt'>): boolean {
  return isClearedThroughTimestamp(chat.clearedAt || null, chat.lastMessageAt || null);
}

function isMessageHiddenByContactClear(contact: Pick<ChatContact, 'clearedAt'>, message: ChatMessage): boolean {
  const clearedAtMs = getTimestampMs(contact.clearedAt || null);
  const messageSentAtMs = getTimestampMs(message.sentAt);

  return clearedAtMs !== null && messageSentAtMs !== null && messageSentAtMs <= clearedAtMs;
}

function isNextContactStillCoveredByClear(currentContact: ChatContact, nextContact: ChatContact): boolean {
  const clearedAtMs = getTimestampMs(currentContact.clearedAt || null);
  const nextLastMessageAtMs = getTimestampMs(nextContact.lastMessageAt || null);

  return clearedAtMs !== null && (nextLastMessageAtMs === null || nextLastMessageAtMs <= clearedAtMs);
}

function isClearedThroughTimestamp(clearedAt: string | null, lastMessageAt: string | null): boolean {
  const clearedAtMs = getTimestampMs(clearedAt);

  if (clearedAtMs === null) {
    return false;
  }

  const lastMessageAtMs = getTimestampMs(lastMessageAt);

  return lastMessageAtMs === null || lastMessageAtMs <= clearedAtMs;
}

function getTimestampMs(value: string | null | undefined): number | null {
  if (!value) {
    return null;
  }

  const timestampMs = Date.parse(value);

  return Number.isFinite(timestampMs) ? timestampMs : null;
}

function mergeChatContactCachedPhoto(
  currentContact: ChatContact | undefined,
  nextContact: ChatContact
): ChatContact {
  if (
    currentContact?.profilePhotoCacheKey &&
    currentContact.profilePhotoCacheKey === nextContact.profilePhotoCacheKey &&
    currentContact.profilePhotoUrl?.startsWith('file:')
  ) {
    return {
      ...nextContact,
      profilePhotoUrl: currentContact.profilePhotoUrl
    };
  }

  return nextContact;
}

function upsertChatContact(currentContacts: ChatContact[], nextContact: ChatContact): ChatContact[] {
  const contactById = new Map<string, ChatContact>();

  currentContacts.forEach((contact) => {
    contactById.set(contact.contactId, contact);
  });
  contactById.set(
    nextContact.contactId,
    mergeChatContactVisibleState(contactById.get(nextContact.contactId), nextContact)
  );

  return sortChatContacts([...contactById.values()]);
}

function sortChatContacts(contacts: ChatContact[]): ChatContact[] {
  return [...contacts].sort(compareChatContacts);
}

function areChatContactListsEqual(firstContacts: ChatContact[], secondContacts: ChatContact[]): boolean {
  if (firstContacts.length !== secondContacts.length) {
    return false;
  }

  return firstContacts.every((firstContact, index) =>
    getChatContactListFingerprint(firstContact) === getChatContactListFingerprint(secondContacts[index])
  );
}

function getChatContactListFingerprint(contact: ChatContact): string {
  return JSON.stringify({
    chatType: contact.chatType || 'DIRECT',
    clearedAt: contact.clearedAt || null,
    contactId: contact.contactId,
    conversationId: contact.conversationId,
    displayName: contact.displayName,
    hasActiveDevice: contact.hasActiveDevice,
    initials: contact.initials,
    isArchived: contact.isArchived === true,
    isDepartmentDefault: contact.isDepartmentDefault === true,
    isFavorite: contact.isFavorite === true,
    isSpam: contact.isSpam === true,
    isOnline: contact.isOnline === true,
    lastMessageAt: contact.lastMessageAt || null,
    lastSeenAt: contact.lastSeenAt || null,
    memberCount: contact.memberCount || 0,
    memberPolicy: contact.memberPolicy || null,
    members: (contact.members || [])
      .map((member) => ({
        displayName: member.displayName,
        initials: member.initials,
        profilePhotoCacheKey: member.profilePhotoCacheKey || null,
        profilePhotoUrl: member.profilePhotoUrl || null,
        role: member.role,
        roleName: member.roleName,
        uid: member.uid
      }))
      .sort((first, second) => first.uid.localeCompare(second.uid)),
    messagePermissionMode: contact.messagePermissionMode || null,
    phoneFormatted: contact.phoneFormatted || null,
    phoneMasked: contact.phoneMasked || null,
    preview: contact.preview,
    profilePhotoCacheKey: contact.profilePhotoCacheKey || null,
    profilePhotoUrl: contact.profilePhotoUrl || null,
    role: contact.role,
    roleName: contact.roleName,
    spammedAt: contact.spammedAt || null,
    status: contact.status,
    trashSegments: (contact.trashSegments || []).map((segment) => ({
      deletedAtMs: segment.deletedAtMs,
      endAtMs: segment.endAtMs,
      expiresAtMs: segment.expiresAtMs,
      segmentId: segment.segmentId,
      startAtMs: segment.startAtMs
    })),
    unreadCount: contact.unreadCount || 0
  });
}

function compareChatContacts(first: ChatContact, second: ChatContact): number {
  if (first.lastMessageAt && second.lastMessageAt) {
    return second.lastMessageAt.localeCompare(first.lastMessageAt);
  }

  if (first.lastMessageAt) {
    return -1;
  }

  if (second.lastMessageAt) {
    return 1;
  }

  return first.displayName.localeCompare(second.displayName);
}

function uniqueChatMessages(messages: ChatMessage[]): ChatMessage[] {
  const messageById = new Map<string, ChatMessage>();

  messages.forEach((message) => {
    const existingMessage = messageById.get(message.messageId);

    messageById.set(message.messageId, mergeChatMessageWithLocalState(existingMessage, message));
  });

  return [...messageById.values()].sort((first, second) =>
    first.sentAt.localeCompare(second.sentAt)
  );
}

function mergeChatMessageWithLocalState(
  existingMessage: ChatMessage | undefined,
  nextMessage: ChatMessage
): ChatMessage {
  if (!existingMessage) {
    return nextMessage;
  }

  const mediaItems = mergeChatMessageMediaItems(
    getMessageMediaItems(existingMessage),
    getMessageMediaItems(nextMessage)
  );
  const media = mergeChatMessageMedia(
    getMessageMedia(existingMessage),
    getMessageMedia(nextMessage)
  ) || mediaItems[0] || null;
  const image = media?.kind === 'image'
    ? toChatImageAttachment(media)
    : null;

  return {
    ...existingMessage,
    ...nextMessage,
    image,
    media,
    mediaItems,
    reactions: Array.isArray(nextMessage.reactions)
      ? nextMessage.reactions
      : existingMessage.reactions || nextMessage.reactions || []
  };
}

function mergeChatMessageMediaItems(
  existingMediaItems: ChatMediaAttachment[],
  nextMediaItems: ChatMediaAttachment[]
): ChatMediaAttachment[] {
  if (!existingMediaItems.length && !nextMediaItems.length) {
    return [];
  }

  const longestLength = Math.max(existingMediaItems.length, nextMediaItems.length);
  const mergedItems: ChatMediaAttachment[] = [];

  for (let index = 0; index < longestLength; index += 1) {
    const mergedMedia = mergeChatMessageMedia(existingMediaItems[index] || null, nextMediaItems[index] || null);

    if (mergedMedia) {
      mergedItems.push(mergedMedia);
    }
  }

  return mergedItems;
}

function mergeChatMessageMedia(
  existingMedia: ChatMediaAttachment | null,
  nextMedia: ChatMediaAttachment | null
): ChatMediaAttachment | null {
  if (!existingMedia && !nextMedia) {
    return null;
  }

  const existingLocalUri = getMediaLocalUri(existingMedia);
  const nextLocalUri = getMediaLocalUri(nextMedia);
  const localUri = nextLocalUri || existingLocalUri || undefined;
  const mergedMedia: ChatMediaAttachment = {
    ...(existingMedia || {}),
    ...(nextMedia || {}),
    localUri
  } as ChatMediaAttachment;

  if (existingLocalUri && !nextLocalUri) {
    mergedMedia.transferStatus = existingMedia?.transferStatus === 'failed'
      ? 'failed'
      : existingMedia?.transferStatus === 'uploading' || existingMedia?.transferStatus === 'queued'
        ? existingMedia.transferStatus
        : 'available';
    mergedMedia.transferProgress = mergedMedia.transferStatus === 'available'
      ? 1
      : existingMedia?.transferProgress;
  } else if (localUri && !mergedMedia.transferStatus && mergedMedia.mediaId) {
    mergedMedia.transferStatus = 'available';
    mergedMedia.transferProgress = 1;
  }

  return mergedMedia;
}

function toChatImageAttachment(media: ChatMediaAttachment): ChatImageAttachment {
  return {
    ...media,
    contentType: 'image/jpeg',
    height: media.height || 1,
    kind: 'image',
    width: media.width || 1
  };
}

function applyMediaUpdateToMessage(
  message: ChatMessage,
  media: ChatMediaAttachment,
  mediaIndex?: number
): ChatMessage {
  const currentMediaItems = getMessageMediaItems(message);

  if (typeof mediaIndex === 'number' && currentMediaItems.length > 1) {
    const nextMediaItems = currentMediaItems.map((mediaItem, index) =>
      index === mediaIndex ? media : mediaItem
    );
    const primaryMedia = nextMediaItems[0] || media;

    return {
      ...message,
      image: primaryMedia.kind === 'image' ? toChatImageAttachment(primaryMedia) : null,
      media: primaryMedia,
      mediaItems: nextMediaItems
    };
  }

  return {
    ...message,
    image: media.kind === 'image' ? toChatImageAttachment(media) : null,
    media,
    mediaItems: currentMediaItems.length > 1 ? currentMediaItems : []
  };
}

function sortApprovedEmployees(employees: ApprovedEmployee[]): ApprovedEmployee[] {
  return [...employees].sort((first, second) => {
    const firstName = first.displayName || first.phoneMasked;
    const secondName = second.displayName || second.phoneMasked;

    return firstName.localeCompare(secondName);
  });
}

function upsertApprovedEmployees(
  currentEmployees: ApprovedEmployee[],
  nextEmployees: ApprovedEmployee[]
): ApprovedEmployee[] {
  const employeeById = new Map<string, ApprovedEmployee>();

  currentEmployees.forEach((employee) => {
    employeeById.set(employee.approvedPhoneId, employee);
  });

  nextEmployees.forEach((employee) => {
    employeeById.set(employee.approvedPhoneId, employee);
  });

  return [...employeeById.values()];
}

function getInitials(name: string): string {
  const initials = name
    .trim()
    .split(/\s+/)
    .filter(Boolean)
    .map((part) => {
      const firstLetter = /[A-Za-z]/.exec(part)?.[0];
      return firstLetter || part[0];
    })
    .join('')
    .slice(0, 2)
    .toUpperCase();

  return initials || '?';
}

function formatEmployeeStatus(status: string): string {
  if (status === 'INVITED') {
    return 'Invited';
  }

  if (status === 'ACTIVE') {
    return 'Active';
  }

  if (status === 'DEACTIVATED') {
    return 'Deactivated';
  }

  if (status === 'SUSPENDED') {
    return 'Suspended';
  }

  if (status === 'ARCHIVED') {
    return 'Archived';
  }

  if (status === 'DELETED') {
    return 'Deleted';
  }

  return status.charAt(0).toUpperCase() + status.slice(1).toLowerCase();
}

function formatSettingValue(value: string): string {
  return value
    .split(/[_-]+/g)
    .filter(Boolean)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1).toLowerCase())
    .join(' ') || 'Not set';
}

function normalizeOrganizationDeletionConfirmation(value: string): string {
  return value.trim().replace(/\s+/g, ' ').toUpperCase();
}

function getContactDisplayName(contact: Contacts.ExistingContact): string | undefined {
  const displayName = contact.name || [contact.firstName, contact.lastName].filter(Boolean).join(' ');
  return displayName.trim() || undefined;
}

async function getContactWithPhoneNumbers(
  contact: Contacts.ExistingContact
): Promise<Contacts.ExistingContact> {
  if (contact.phoneNumbers?.length) {
    return contact;
  }

  const contactWithPhoneNumbers = await Contacts.getContactByIdAsync(contact.id, [
    Contacts.Fields.Name,
    Contacts.Fields.FirstName,
    Contacts.Fields.LastName,
    Contacts.Fields.PhoneNumbers
  ]);

  return contactWithPhoneNumbers || contact;
}

async function loadBatchContactCandidates(): Promise<BatchContactCandidate[]> {
  const contactsAvailable = await Contacts.isAvailableAsync();

  if (!contactsAvailable) {
    throw new Error('Contacts are not available on this device.');
  }

  const permission = await Contacts.requestPermissionsAsync();

  if (permission.status !== 'granted') {
    throw new Error('Contact permission is required for batch import.');
  }

  const response = await Contacts.getContactsAsync({
    fields: [
      Contacts.Fields.Name,
      Contacts.Fields.FirstName,
      Contacts.Fields.LastName,
      Contacts.Fields.PhoneNumbers
    ],
    pageSize: 5000
  });
  const candidateByPhoneNumber = new Map<string, BatchContactCandidate>();

  response.data.forEach((contact) => {
    const displayName = getContactDisplayName(contact) || 'Unnamed contact';

    (contact.phoneNumbers || []).forEach((phoneNumber, index) => {
      const normalizedPhoneNumber = normalizeContactPhoneNumber(phoneNumber);

      if (!normalizedPhoneNumber || candidateByPhoneNumber.has(normalizedPhoneNumber)) {
        return;
      }

      const phoneMasked = maskLocalPhoneNumber(normalizedPhoneNumber);
      const label = phoneNumber.label ? `${phoneNumber.label}: ` : '';

      candidateByPhoneNumber.set(normalizedPhoneNumber, {
        displayName,
        id: `${contact.id}-${phoneNumber.id || index}-${normalizedPhoneNumber}`,
        phoneMasked,
        phoneNumber: normalizedPhoneNumber,
        subtitle: `${label}${phoneMasked}`
      });
    });
  });

  return [...candidateByPhoneNumber.values()].sort((first, second) =>
    first.displayName.localeCompare(second.displayName)
  );
}

function normalizeContactPhoneNumber(phoneNumber: Contacts.PhoneNumber): string | null {
  const rawPhoneNumber = (phoneNumber.number || phoneNumber.digits || '').trim();

  if (!rawPhoneNumber) {
    return null;
  }

  const digits = rawPhoneNumber.replace(/\D/g, '');

  if (rawPhoneNumber.startsWith('+')) {
    return validateE164Phone(`+${digits}`);
  }

  const countryCode = phoneNumber.countryCode?.toLowerCase();

  if (countryCode === 'us' || countryCode === 'ca') {
    return normalizeNanpPhone(digits);
  }

  if (countryCode === 'mx') {
    return normalizeCountryPhone(digits, '52', 10);
  }

  if (countryCode === 'gb' || countryCode === 'uk') {
    const ukDigits = digits.startsWith('44')
      ? digits.slice(2)
      : digits.startsWith('0')
        ? digits.slice(1)
        : digits;

    return validateE164Phone(`+44${ukDigits}`);
  }

  if (digits.length === 10 || (digits.length === 11 && digits.startsWith('1'))) {
    return normalizeNanpPhone(digits);
  }

  return null;
}

